	[6] = {
		voice = {
			{561297, "pick", "sylvanaswindrunnergreeting01", "We are the Forsaken. We will slaughter anyone who stands in our way."},
			{561327, "pick", "sylvanaswindrunnergreeting02", "What are we if not slaves to this torment?"},
			{561346, "pick", "sylvanaswindrunnergreeting03", "What joy is there in this curse?"},
			{561301, "pick", "sylvanaswindrunnergreeting04", "I have no time for games."},
			{561350, "pick", "fs_sylvanas_fs06", "The Dark Lady watches over you. Make haste."},
			{561280, "pick", "sylvanaswindrunneraggro02", "May my aim be true."},
			{561322, "pick", "sylvanaswindrunneraggro01", "Let none survive."},
			{897336, "pick", "vo_54_or_sylvanas_event_1", "I will not fall. Not here, not now."},
			{1248858, "pick", "vo_70_lady_sylvanas_windrunner_63", "One shot, one kill."},
			{1248860, "pick", "vo_70_lady_sylvanas_windrunner_64", "Too easy."},
			{1245013, "pick", "vo_70_lady_sylvanas_windrunner_33", "No. The Forsaken will never stop fighting."},
			{1801004, "pick", "vo_735_lady_sylvanas_windrunner_34_f", "Greetings, champion."},
			{1801007, "pick", "vo_735_lady_sylvanas_windrunner_37_f", "Serve me well, and you will be rewarded."},
			{2464036, "aggro", "vo_81_lady_sylvanas_windrunner_preaggro_01", "Huh?"},
			{2464037, "aggro", "vo_81_lady_sylvanas_windrunner_preaggro_02", "Huh?"},
			{2464038, "aggro", "vo_81_lady_sylvanas_windrunner_preaggro_03", "Ahh..."},
			{573170, "aggro", "vo_et_echoofsylvanas_aggro_01", "Another band of Deathwing's converts? I'll be sure your death is especially painful."},
			{2464033, "shout", "vo_81_lady_sylvanas_windrunner_battleshout_01", "Brrrrrrrrrr!"},
			{2464034, "shout", "vo_81_lady_sylvanas_windrunner_battleshout_02", "HAAAAA!"},
			{2464035, "shout", "vo_81_lady_sylvanas_windrunner_battleshout_03", "HAAAAA!"},
			{897354, "alert", "vo_54_or_sylvanas_intro_01", "I can raise your dead, Regent Lord. Your Rangers can fight again."},
			{897356, "alert", "vo_54_or_sylvanas_intro_02", "I'm sorry to see your lack of commitment. Hmm... what of the human corpses?"},
			{897358, "alert", "vo_54_or_sylvanas_intro_03", "Rise, my angels! Let your screams fill the streets of Orgrimmar with terror!"},
			{897360, "alert", "vo_54_or_sylvanas_intro_04", "I see the dragon maw have thrown in their lot with Garrosh."},
			{897362, "alert", "vo_54_or_sylvanas_intro_05", "My arrows alone cannot bring that monstrosity down."},
			{897364, "alert", "vo_54_or_sylvanas_intro_06", "Oh, bring her down quick, so I can wrap my fingers around her neck."},
			{561287, "alert", "wg_sylvanas_horintro01", "Lady Proudmoore, the Warchief speaks the truth. This subterfuge was set in motion by Vermothross and Grand Apothecary Putress. It was not the Horde's doing."},
			{561319, "alert", "wg_sylvanas_horintro02", "As the combined horde and Alliance forces began their assault upon the Wrathgate, an uprising broke out in the Undercity. Vermothros and hordes of his demonic brethren attacked. Hundreds of my people were slain in the coup. I barely managed to escape with my life."},
			{5225414, "line", "vo_1017_lady_sylvanas_windrunner_01_f", "Greetings, my most loyal ally. I speak to you now from beyond the veil of death."},
			{5225415, "line", "vo_1017_lady_sylvanas_windrunner_02_f", "Here, in this place of eternal darkness, my work, my penance, continues."},
			{5225416, "line", "vo_1017_lady_sylvanas_windrunner_03_f", "Though the maw is an unlikely place for one to find peace, each soul I rescue helps mine feel a little more... whole."},
			{5225417, "line", "vo_1017_lady_sylvanas_windrunner_04_f", "As I ponder my deeds since being raised into undeath, I have many regrets, things said and choices made that I wish could be taken back."},
			{5225418, "line", "vo_1017_lady_sylvanas_windrunner_05_f", "But there is one thing for which I will always be proud, helping the Forsaken find their place in a world that shunned them."},
			{5225419, "line", "vo_1017_lady_sylvanas_windrunner_06_f", "My time to lead may be over, but I will always stand with you against those who would cast you out and call you monsters."},
			{5225420, "line", "vo_1017_lady_sylvanas_windrunner_07_f", "Under the leadership of the Desolate Council, a new group of voices has arisen to represent all forsaken."},
			{5225421, "line", "vo_1017_lady_sylvanas_windrunner_08_f", "Stand proud in the horde, and know that all of you were so much more than arrows in my quiver."},
			{5225422, "line", "vo_1017_lady_sylvanas_windrunner_09_f", "As much as the family I was born into, you will always be my people. And one day, I do hope to walk among you once again."},
			{5225423, "line", "vo_1017_lady_sylvanas_windrunner_10_f", "I must go. There are many more souls yet to be freed, among them one that is most dear to me."},
			{5225424, "line", "vo_1017_lady_sylvanas_windrunner_11_f", "Shurello Rama, my friend."},
			{897338, "line", "vo_54_or_sylvanas_event_2", "I feel better already."},
			{897340, "line", "vo_54_or_sylvanas_event_3", "Huh, a bold move."},
			{897342, "line", "vo_54_or_sylvanas_event_4", "She's attacking the towers again!"},
			{897344, "line", "vo_54_or_sylvanas_event_5", "And there goes the other one."},
			{897346, "line", "vo_54_or_sylvanas_event_6", "You do realize we are directly below it, right?"},
			{897348, "line", "vo_54_or_sylvanas_event_7", "I had kind of hoped you had perished."},
			{897350, "line", "vo_54_or_sylvanas_event_8", "Ha, if he's not dead."},
			{897352, "line", "vo_54_or_sylvanas_event_9", "I can't wait to see the look on his face when I animate his corpse. We better win this battle!"},
			{897366, "line", "vo_54_or_sylvanas_special", "Garrosh really has gone all out this time, hasn't he? I expected more spikes, honestly."},
			{897368, "line", "vo_54_or_sylvanas_spell_1", "A hail of death approaches, bring them to their fate."},
			{1406277, "line", "vo_703_lady_sylvanas_windrunner_01", "Champion, come forward!"},
			{1406278, "line", "vo_703_lady_sylvanas_windrunner_02", "Turn and face your peers, champion, so that they may bear witness to your ruthlessness and cunning."},
			{1406279, "line", "vo_703_lady_sylvanas_windrunner_03", "Before you stands the Horde's greatest champion, hero of countless victories against our unrelenting foe."},
			{1406280, "line", "vo_703_lady_sylvanas_windrunner_04", "The ancient weapon they wield inspires fear in the hearts of those who would threaten our way of life."},
			{1406281, "line", "vo_703_lady_sylvanas_windrunner_05", "So join me, heroes, in honoring our champion, Bane of the Alliance."},
			{1406282, "line", "vo_703_lady_sylvanas_windrunner_06", "For the Horde!"},
			{1406829, "line", "vo_703_lady_sylvanas_windrunner_07", "Fast or raw, I have not seen it in years. That's a windrunner family heirloom you have slung across your back."},
			{1406830, "line", "vo_703_lady_sylvanas_windrunner_08", "My mother passed it down to my eldest sister. May it bring you better fortune than it did her."},
			{1406831, "line", "vo_703_lady_sylvanas_windrunner_09", "Remember, champion, that Thostora represents my family's legacy, my legacy. The deeds you perform while wielding it reflect upon me."},
			{1406832, "line", "vo_703_lady_sylvanas_windrunner_10", "It is fitting that the bow be in the hands of so skilled a marksman. I trust you will remain worthy of it. Do not disappoint me."},
			{1449340, "line", "vo_703_lady_sylvanas_windrunner_11_f", "A decisive victory, these alliance lapdogs scatter before the might of the Horde!"},
			{1449341, "line", "vo_703_lady_sylvanas_windrunner_12_f", "Grey mains forces hold this warden tower! Break their ranks! Show no mercy!"},
			{1449364, "line", "vo_703_lady_sylvanas_windrunner_13_f", "You"},
			{1449365, "line", "vo_703_lady_sylvanas_windrunner_14_f", "You"},
			{1449368, "line", "vo_703_lady_sylvanas_windrunner_15_f", "You"},
			{1449369, "line", "vo_703_lady_sylvanas_windrunner_16_f", "You"},
			{1238028, "line", "vo_70_lady_sylvanas_windrunner_01", "You"},
			{1238026, "line", "vo_70_lady_sylvanas_windrunner_02", "You"},
			{1238032, "line", "vo_70_lady_sylvanas_windrunner_03", "You"},
			{1238040, "line", "vo_70_lady_sylvanas_windrunner_04", "You"},
			{1238084, "line", "vo_70_lady_sylvanas_windrunner_05", "You"},
			{1238088, "line", "vo_70_lady_sylvanas_windrunner_06", "You"},
			{1238090, "line", "vo_70_lady_sylvanas_windrunner_07", "You"},
			{1238094, "line", "vo_70_lady_sylvanas_windrunner_08", "You"},
			{1238097, "line", "vo_70_lady_sylvanas_windrunner_09", "You"},
			{1238099, "line", "vo_70_lady_sylvanas_windrunner_10", "You"},
			{1238102, "line", "vo_70_lady_sylvanas_windrunner_11", "You"},
			{1238110, "line", "vo_70_lady_sylvanas_windrunner_12", "You"},
			{1238117, "line", "vo_70_lady_sylvanas_windrunner_13", "You"},
			{1238121, "line", "vo_70_lady_sylvanas_windrunner_14", "You"},
			{1238125, "line", "vo_70_lady_sylvanas_windrunner_15", "You"},
			{1238169, "line", "vo_70_lady_sylvanas_windrunner_16", "You"},
			{1243488, "line", "vo_70_lady_sylvanas_windrunner_17", "The Alliance will be upon us soon, and we have nowhere to run."},
			{1243490, "line", "vo_70_lady_sylvanas_windrunner_18", "Do not question me, Nefanos. Now go. Make for the eternity and bring this hero with you."},
			{1243492, "line", "vo_70_lady_sylvanas_windrunner_19", "Organize our defenses beginning with the rear. I want bat riders in the air and catapults at the ready."},
			{1244135, "line", "vo_70_lady_sylvanas_windrunner_20", "What have we here? Another one of Greymane's mercenaries?"},
			{1244137, "line", "vo_70_lady_sylvanas_windrunner_21", "Ah, my loyal hero."},
			{1244139, "line", "vo_70_lady_sylvanas_windrunner_22", "No matter, soon you will witness the birth of a new age."},
			{1244141, "line", "vo_70_lady_sylvanas_windrunner_23", "You must not languish here. The Aegis cannot fall into enemy hands."},
			{1244143, "line", "vo_70_lady_sylvanas_windrunner_24", "If you ever make it out of here, that is."},
			{1244145, "line", "vo_70_lady_sylvanas_windrunner_25", "The future of the Horde depends on you and me. Find your way back to Stormheim. I will be waiting."},
			{1244999, "line", "vo_70_lady_sylvanas_windrunner_26", "Are you familiar with the Vrykul? Towering, brutish warriors from an ancient stock. Subtlety is not a value they hold in high regard."},
			{1245001, "line", "vo_70_lady_sylvanas_windrunner_27", "Their legends speak of the Aegis of Aggramar. To claim it, one must undergo some kind of trial. One must be... worthy."},
			{1245003, "line", "vo_70_lady_sylvanas_windrunner_28", "The new catapults are faster and more powerful than ever before. I have our goblin allies to thank for that."},
			{1245005, "line", "vo_70_lady_sylvanas_windrunner_29", "I trust you are more than capable of handling whatever trials stand between you and the ages."},
			{1245007, "line", "vo_70_lady_sylvanas_windrunner_30", "Truthfully, Stormheim holds another treasure, one that I will be pursuing by my own means."},
			{1245009, "line", "vo_70_lady_sylvanas_windrunner_31", "Nathanos has been training a new generation of rangers. They represent both our past and our future."},
			{1245011, "line", "vo_70_lady_sylvanas_windrunner_32", "I think often about our future hero. My people cannot reproduce. Are we not destined then to wither away eventually?"},
			{1245015, "line", "vo_70_lady_sylvanas_windrunner_34", "Not while I reign. Not when there are still beings out there with the power to stop death."},
			{1245021, "line", "vo_70_lady_sylvanas_windrunner_35", "Good. Send a bat. Tell them we are leaving shortly."},
			{1245025, "line", "vo_70_lady_sylvanas_windrunner_36", "Champion, as your new Warchief, I share with you the burden of securing our future."},
			{1245027, "line", "vo_70_lady_sylvanas_windrunner_37", "To that end, my fleet is preparing to sail for the Broken Isles. When you set foot in Stormheim, you shall have the full power of the Forsaken at your back.\""},
			{1245029, "line", "vo_70_lady_sylvanas_windrunner_38", "Together, we will ensure that no one can oppose the might of the Horde."},
			{1248590, "line", "vo_70_lady_sylvanas_windrunner_39", "Gul'dan, you will pay for this!"},
			{1248608, "line", "vo_70_lady_sylvanas_windrunner_40", "The armies of Azeroth will triumph this day, together!"},
			{1248618, "line", "vo_70_lady_sylvanas_windrunner_41", "Monsters from the fail fire, hard forces be ready"},
			{1248630, "line", "vo_70_lady_sylvanas_windrunner_42", "Another wave incoming!"},
			{1248638, "line", "vo_70_lady_sylvanas_windrunner_43", "Let's go, Horde! It's time to show the Alliance how we slay demons!"},
			{1248652, "line", "vo_70_lady_sylvanas_windrunner_44", "All Horde forces on my target! We're going to bring down that demon!"},
			{1248660, "line", "vo_70_lady_sylvanas_windrunner_45", "Consider your job done then, Ryn."},
			{1248662, "line", "vo_70_lady_sylvanas_windrunner_46", "All yours, Alliance!"},
			{1248668, "line", "vo_70_lady_sylvanas_windrunner_47", "No time to gloat, Ryn. We've got to stop Gul'dan before he summons another one of those things."},
			{1248672, "line", "vo_70_lady_sylvanas_windrunner_48", "We'll take the ridge and cover your flank."},
			{1248676, "line", "vo_70_lady_sylvanas_windrunner_49", "Good luck, Varian."},
			{1248691, "line", "vo_70_lady_sylvanas_windrunner_50", "Take up positions. We hold them off. We have to."},
			{1248695, "line", "vo_70_lady_sylvanas_windrunner_51", "Pull Vayne back to my position! Close ranks!"},
			{1248699, "line", "vo_70_lady_sylvanas_windrunner_52", "Let's Chatting Rin kill him already!"},
			{1248709, "line", "vo_70_lady_sylvanas_windrunner_53", "Vol'jin! Pull him back! Keep your lines steady! We have to hold!"},
			{1248713, "line", "vo_70_lady_sylvanas_windrunner_54", "Everyone, pull back to me! We make our stand here!"},
			{1248735, "line", "vo_70_lady_sylvanas_windrunner_55", "There are so many of them."},
			{1248737, "line", "vo_70_lady_sylvanas_windrunner_56", "There's nothing we can do! The ridge is lost! Court forces, if you value your lives, cut a path through to the shore. We have to get out of here, or there won't be anyone left to fight."},
			{1248824, "line", "vo_70_lady_sylvanas_windrunner_57", "knock your arrows hold fire"},
			{1248830, "line", "vo_70_lady_sylvanas_windrunner_58", "It's about time you showed up."},
			{1248838, "line", "vo_70_lady_sylvanas_windrunner_59", "You heard him, Rangers! We cut those demons down! Fire a volley on my mark! Now!"},
			{1248842, "line", "vo_70_lady_sylvanas_windrunner_60", "Well, that was invigorating. Now how did they manage to get so many demons here so quickly?"},
			{1248848, "line", "vo_70_lady_sylvanas_windrunner_61", "And now we know how to destroy them. It's them or us! Let's get moving so we make sure it's not us."},
			{1248850, "line", "vo_70_lady_sylvanas_windrunner_62", "This is Argent Crusade Insignia."},
			{1248862, "line", "vo_70_lady_sylvanas_windrunner_65", "That's half of the city down. This is going better than expected."},
			{1248864, "line", "vo_70_lady_sylvanas_windrunner_66", "right to the face!"},
			{1248866, "line", "vo_70_lady_sylvanas_windrunner_67", "We'll never bow to you!"},
			{1248904, "line", "vo_70_lady_sylvanas_windrunner_68", "This was too easy. Something's wrong."},
			{1248910, "line", "vo_70_lady_sylvanas_windrunner_69", "Anyone have any ideas how we're going to get across this thing?"},
			{1248914, "line", "vo_70_lady_sylvanas_windrunner_70", "Convenient."},
			{1782210, "line", "vo_735_lady_sylvanas_windrunner_01_f", "Chieftain Bloodhoof, have our champion join you for your feast in Thunderbluff. By the time dessert is served, I want the oath of loyalty to the Horde."},
			{1782211, "line", "vo_735_lady_sylvanas_windrunner_02_f", "What have you to say, chieftain?"},
			{1782212, "line", "vo_735_lady_sylvanas_windrunner_03_f", "I accept your oath of loyalty. The Horde offers its protection and expects your obedience."},
			{1782213, "line", "vo_735_lady_sylvanas_windrunner_04_f", "For the Horde!"},
			{1800914, "line", "vo_735_lady_sylvanas_windrunner_05_f", "Do not return until Suramar's strength is pledged to the Horde."},
			{1800915, "line", "vo_735_lady_sylvanas_windrunner_06_f", "Indeed, First Arcanist."},
			{1800916, "line", "vo_735_lady_sylvanas_windrunner_07_f", "For millenia, Suramar stood alone. This day, you become part of something greater. I accept your oath of service, Alistra."},
			{1800917, "line", "vo_735_lady_sylvanas_windrunner_08_f", "For the Horde!"},
			{1800934, "line", "vo_735_lady_sylvanas_windrunner_09_f", "Leaders of the Horde, I summoned you here, along with one of our greatest champions, because our enemies are gathering their strength."},
			{1800935, "line", "vo_735_lady_sylvanas_windrunner_10_f", "The Alliance is scouring the far corners of Azeroth in search of every advantage against us. We must do the same."},
			{1800936, "line", "vo_735_lady_sylvanas_windrunner_11_f", "War is coming. We need fresh blood added to the ranks of the Horde. What say you?"},
			{1800937, "line", "vo_735_lady_sylvanas_windrunner_12_f", "A simple people, but strong. They would be a boon on the battlefield."},
			{1800938, "line", "vo_735_lady_sylvanas_windrunner_13_f", "Even without the Nightwell, Suramar holds vast arcane resources, a most useful arrow added to my quiver."},
			{1800939, "line", "vo_735_lady_sylvanas_windrunner_14_f", "Each option would have its uses. I believe our champion knows these peoples. Which potential ally do you suggest we pursue first?"},
			{1800957, "line", "vo_735_lady_sylvanas_windrunner_15_f", "Ah, the young hero comes before me. I am told you show great promise. Let us hope these reports prove true."},
			{1800958, "line", "vo_735_lady_sylvanas_windrunner_16_f", "The High Mountain Taran possess strength and courage. We will have need of such qualities in the days to come."},
			{1800959, "line", "vo_735_lady_sylvanas_windrunner_17_f", "The Nightborne are a wise and powerful people. The ancient knowledge you possess will prove a great boon to our cause."},
			{1800960, "line", "vo_735_lady_sylvanas_windrunner_18_f", "The Horde has many rivals in this world. Some call us enemies, others call us outcasts, but we find strength in unity and in defiance of those who would challenge our freedom."},
			{1800961, "line", "vo_735_lady_sylvanas_windrunner_19_f", "Rest assured, I will be taking note of your progress. As War Chief, I expect much of you, and I reward those who serve me well."},
			{1800962, "line", "vo_735_lady_sylvanas_windrunner_20_f", "Enough of these pleasantries. You have much to prove, hero. Wherever your path takes you, know that you fight for the Horde."},
			{1800981, "line", "vo_735_lady_sylvanas_windrunner_21_f", "You have observed our operations in Syllathus Champion. Clearly the Alliance is doing everything in its power to undermine our efforts."},
			{1800982, "line", "vo_735_lady_sylvanas_windrunner_22_f", "The Horde's selfless leadership in the war against the Legion has left our ranks depleted. Our enemies slather at the thought of stealing what is ours. We will not let them."},
			{1800983, "line", "vo_735_lady_sylvanas_windrunner_23_f", "I have authorized the building of an embassy in Olgromah. From it we will win others to our cause. Meet me there at once."},
			{1800994, "line", "vo_735_lady_sylvanas_windrunner_24_f", "Go. I have much to do."},
			{1800995, "line", "vo_735_lady_sylvanas_windrunner_25_f", "Serve the horde, serve me."},
			{1800996, "line", "vo_735_lady_sylvanas_windrunner_26_f", "We will bring the Alliance to its knees."},
			{1800997, "line", "vo_735_lady_sylvanas_windrunner_27_f", "I will grow the ranks of the Forsaken, one way or another."},
			{1800998, "line", "vo_735_lady_sylvanas_windrunner_28_f", "All will serve the Horde in time."},
			{1800999, "line", "vo_735_lady_sylvanas_windrunner_29_f", "We will claim what is ours."},
			{1801000, "line", "vo_735_lady_sylvanas_windrunner_30_f", "The lifeblood of Azeroth belongs to the Horde."},
			{1801001, "line", "vo_735_lady_sylvanas_windrunner_31_f", "State your business to your Warchief."},
			{1801002, "line", "vo_735_lady_sylvanas_windrunner_32_f", "I trust you will not waste my time."},
			{1801003, "line", "vo_735_lady_sylvanas_windrunner_33_f", "Come forward."},
			{1801005, "line", "vo_735_lady_sylvanas_windrunner_35_f", "Our true work is just beginning."},
			{1801006, "line", "vo_735_lady_sylvanas_windrunner_36_f", "There will be a new future for the Horde."},
			{1801008, "line", "vo_735_lady_sylvanas_windrunner_38_f", "No doubt I am your favorite win-runner sister, right? Right?"},
			{1801009, "line", "vo_735_lady_sylvanas_windrunner_39_f", "I have taken note of your progress. It seems I may have to send you to Nathanos for remedial training."},
			{1801010, "line", "vo_735_lady_sylvanas_windrunner_40_f", "Did you think I would not notice the way you leer at my dark rangers? I suggest you keep your eyes and thoughts to yourself."},
			{1801011, "line", "vo_735_lady_sylvanas_windrunner_41_f", "Plans? Little old me? What sort of plans could I possibly have?"},
			{1993353, "line", "vo_801_lady_sylvanas_windrunner_01_f", "What say you, champion? Are you prepared to pursue a new ally?"},
			{1993354, "line", "vo_801_lady_sylvanas_windrunner_02_f", "The Magha Orcs are legendary for their battle prowess. I will have need of such fearless soldiers in the days ahead."},
			{1993372, "line", "vo_801_lady_sylvanas_windrunner_03_f", "I see the value in this plan, but I thought the door to that other Drano had closed."},
			{1993374, "line", "vo_801_lady_sylvanas_windrunner_04_f", "Our Nightborne allies possess a particular affinity for teleportation. I suggest you draw upon their knowledge to aid you on your journey."},
			{1993377, "line", "vo_801_lady_sylvanas_windrunner_05_f", "Etrig has told me of your people's strength. I trust honor means as much to you as it does to him."},
			{1993380, "line", "vo_801_lady_sylvanas_windrunner_06_f", "I accept your loyalty overlord. Your people are welcome within the gates of Orgrimmar."},
			{1993384, "line", "vo_801_lady_sylvanas_windrunner_07_f", "For the Horde!"},
			{2002702, "line", "vo_801_lady_sylvanas_windrunner_08_f", "These wisps are little more than insects to be crushed. Snuff out each light, one by one, and soon the sky will fill with darkness."},
			{2002703, "line", "vo_801_lady_sylvanas_windrunner_09_f", "That's exactly the kind of message I want to send to Malfurion. Excellent work."},
			{2062634, "line", "vo_801_lady_sylvanas_windrunner_100_f", "But victory demands more than boosting our own strength. It requires hobbling our enemies until they grovel before us."},
			{2062636, "line", "vo_801_lady_sylvanas_windrunner_101_f", "Use the footholds you secured in Kulturas to cripple the boy-king's forces. Shake their faith in their futile cause."},
			{2062637, "line", "vo_801_lady_sylvanas_windrunner_102_f", "Take their hope and you will claim victory for the Horde!"},
			{2062704, "line", "vo_801_lady_sylvanas_windrunner_103_f", "Our goblin allies continue to prove their worth. They have pinpointed deposits of Azerite on islands scattered throughout the vast seas."},
			{2062705, "line", "vo_801_lady_sylvanas_windrunner_104_f", "We must seize the advantage, explore these islands and lay claim to them, before the Alliance does."},
			{2062706, "line", "vo_801_lady_sylvanas_windrunner_105_f", "In war, there are times when a single well-placed blade in the back does more damage than a thousand swords on the battlefield."},
			{2062707, "line", "vo_801_lady_sylvanas_windrunner_106_f", "Work with Garona Halforcen to assemble a unit of the Horde's most cunning and devious operatives. You will dispatch these forces on covert missions throughout Kul Tiras and Zandalor."},
			{2062708, "line", "vo_801_lady_sylvanas_windrunner_107_f", "Use their stealth and guile to reveal weaknesses in the enemy's defenses and exploit them."},
			{2062720, "line", "vo_801_lady_sylvanas_windrunner_108_f", "The world is full of soldiers, Champion, but few truly have the stomach for war. You, it seems, have a genuine taste for it."},
			{2062721, "line", "vo_801_lady_sylvanas_windrunner_109_f", "Though victory still eludes us, it draws closer every day. We must not rest until the last flicker of hope in the boy-king's heart turns to ashes."},
			{2002704, "line", "vo_801_lady_sylvanas_windrunner_10_f", "Azerite emerges amongst the ruins of Darkshore. We must not allow the Alliance to gather a single shard of it."},
			{2062722, "line", "vo_801_lady_sylvanas_windrunner_110_f", "Cold Tiras has become a rallying point for the Alliance. The return of its vaunted navy has emboldened them. But soon those tide-borne Curs will pay the price for defying us."},
			{2062723, "line", "vo_801_lady_sylvanas_windrunner_111_f", "You embody the best of the Horde, champion. I know that you will be the spark that sets Boralus ablaze."},
			{2062724, "line", "vo_801_lady_sylvanas_windrunner_112_f", "For the Horde!"},
			{2066209, "line", "vo_801_lady_sylvanas_windrunner_113_f", "Nathanos, your conversion of Brother Zelling is already yielding results. He has revealed the location of the shipwreck we seek."},
			{2066210, "line", "vo_801_lady_sylvanas_windrunner_114_f", "You must act quickly. Use the cover of night to conceal your search for the remains. Those waters are fraught with Alliance patrols."},
			{2066211, "line", "vo_801_lady_sylvanas_windrunner_115_f", "To ensure your success, I am sending along an operative who possesses a unique set of skills. I believe they will prove quite useful on this mission."},
			{2066222, "line", "vo_801_lady_sylvanas_windrunner_116_f", "Stromgarde was a seat of Alliance power at the heart of the Eastern Kingdoms, before the Keep fell to ruin."},
			{2066223, "line", "vo_801_lady_sylvanas_windrunner_117_f", "Now the boy-king sends his underlings to reclaim it. We cannot allow them to succeed."},
			{2066224, "line", "vo_801_lady_sylvanas_windrunner_118_f", "Our forces are assembled at Argorok. Rally your allies and take strong guard for the Horde!"},
			{2068242, "line", "vo_801_lady_sylvanas_windrunner_119_f", "You were the right arrow for the shot, champion."},
			{2002705, "line", "vo_801_lady_sylvanas_windrunner_11_f", "Very nice, champion. I will have the Azerite added to our reserves."},
			{2068428, "line", "vo_801_lady_sylvanas_windrunner_120_f", "Saurfang has crested the mountains between Darkshore and Felwood. Meet him at Shattersphere Vale and ensure that the passage he seeks is secure."},
			{2068493, "line", "vo_801_lady_sylvanas_windrunner_121_f", "The Alliance seeks to use siege weaponry against us. How quaint. Show them what the Horde is capable of."},
			{2068498, "line", "vo_801_lady_sylvanas_windrunner_122_f", "We struck a significant blow to the reserves, hero. Well done."},
			{2068518, "line", "vo_801_lady_sylvanas_windrunner_123_f", "Azerite emerges amongst the ruins of Darkshore. We must not allow the Alliance to gather a single shard of it."},
			{2068521, "line", "vo_801_lady_sylvanas_windrunner_124_f", "A very nice champion. I will have the Azerite added to our reserves."},
			{2068754, "line", "vo_801_lady_sylvanas_windrunner_125_f", "Another victory."},
			{2068757, "line", "vo_801_lady_sylvanas_windrunner_126_f", "I never doubted you for a moment."},
			{2068760, "line", "vo_801_lady_sylvanas_windrunner_127_f", "These ruins are rich with natural resources. Ours for the taking. Do not allow the Kaldorei to stop us, champion."},
			{2068763, "line", "vo_801_lady_sylvanas_windrunner_128_f", "Alliance saboteurs have infiltrated our foothold. Flush them out. Make them bleed."},
			{2108659, "line", "vo_801_lady_sylvanas_windrunner_129_f", "Hmm, the wisps were dispersing. Excellent. Our plan shows promise."},
			{2002706, "line", "vo_801_lady_sylvanas_windrunner_12_f", "Like Aldor, I draw power from pendants made of moonstone. Do whatever you must to deprive them of these trinkets."},
			{2108660, "line", "vo_801_lady_sylvanas_windrunner_130_f", "Champion, we need to hold the Kaldorei's attention while I devise a solution to our wisp problem."},
			{2108661, "line", "vo_801_lady_sylvanas_windrunner_131_f", "It seems the wisps are susceptible to distraction. We will exploit this weakness to get past them."},
			{2108662, "line", "vo_801_lady_sylvanas_windrunner_132_f", "Sarfang, take a squad into Felwood, seek a path over the mountain into Darkshore, but leave the siege weapons under my command."},
			{2108663, "line", "vo_801_lady_sylvanas_windrunner_133_f", "We will squeeze Malfurion from both sides."},
			{2108664, "line", "vo_801_lady_sylvanas_windrunner_134_f", "Find one or make one time is a luxury we do not possess"},
			{2108665, "line", "vo_801_lady_sylvanas_windrunner_135_f", "Then it is decided. Safang, Nathanos, you will leave at once."},
			{2108666, "line", "vo_801_lady_sylvanas_windrunner_136_f", "The scouting party I led to Malfurion underestimated the Wisps, and they paid the price for doing so."},
			{2108667, "line", "vo_801_lady_sylvanas_windrunner_137_f", "We cannot destroy the Wisps, not in numbers enough to matter, but we may be able to disperse them."},
			{2108668, "line", "vo_801_lady_sylvanas_windrunner_138_f", "Precisely what I was thinking. Champion, would you be so kind as to test out theory?"},
			{2108669, "line", "vo_801_lady_sylvanas_windrunner_139_f", "To Zoramgar, quickly!"},
			{2002707, "line", "vo_801_lady_sylvanas_windrunner_13_f", "I will order our Enchantress to infuse these moonstones with Azerite. Their power now serves the Horde."},
			{2108670, "line", "vo_801_lady_sylvanas_windrunner_140_f", "sappers gather your gear and follow me bring every shredder we have"},
			{2108671, "line", "vo_801_lady_sylvanas_windrunner_141_f", "Azerite. With this in our grasp, all who dared to oppose the Horde will fall."},
			{2108672, "line", "vo_801_lady_sylvanas_windrunner_142_f", "Proceed with caution, champion. It seems the Alliance has beaten us to it."},
			{2108673, "line", "vo_801_lady_sylvanas_windrunner_143_f", "Make quick work of this place."},
			{2108674, "line", "vo_801_lady_sylvanas_windrunner_144_f", "That ship must have come from Darnassus, which means..."},
			{2108675, "line", "vo_801_lady_sylvanas_windrunner_145_f", "I have a crow to hunt."},
			{2108676, "line", "vo_801_lady_sylvanas_windrunner_146_f", "Hmm, I see this makes you uneasy. These ancients have been turned against you, Druid, against their sacred charge."},
			{2108677, "line", "vo_801_lady_sylvanas_windrunner_147_f", "End their existence, or they will coat this forest in our people's blood."},
			{2108678, "line", "vo_801_lady_sylvanas_windrunner_148_f", "Regret nothing. You did well."},
			{2108679, "line", "vo_801_lady_sylvanas_windrunner_149_f", "My victory was inevitable. He was merely wasting my time."},
			{2002708, "line", "vo_801_lady_sylvanas_windrunner_14_f", "The Kaldorei use moon wells to replenish their strength in battle. Draw from the wells what you will, then render them unusable. Am I understood?"},
			{2108680, "line", "vo_801_lady_sylvanas_windrunner_150_f", "Finish him and be done with it. Take a moment if you like. Then take his head. Meet me at the world tree."},
			{2108681, "line", "vo_801_lady_sylvanas_windrunner_151_f", "Wild Bend River is locked in a stalemate, and Malfurion knows it."},
			{2108682, "line", "vo_801_lady_sylvanas_windrunner_152_f", "We must stay the course for now."},
			{2108683, "line", "vo_801_lady_sylvanas_windrunner_153_f", "I will continue leading our soldiers through the wall while we await word from Safang."},
			{2108684, "line", "vo_801_lady_sylvanas_windrunner_154_f", "In the meantime, we will do all that we can to keep the Kaldorei under pressure."},
			{2108685, "line", "vo_801_lady_sylvanas_windrunner_155_f", "We shall not afford them the luxury of a peaceful night's rest. This is war."},
			{2108686, "line", "vo_801_lady_sylvanas_windrunner_156_f", "There will be nowhere to run when next we meet Malfurion."},
			{2108687, "line", "vo_801_lady_sylvanas_windrunner_157_f", "You"},
			{2108688, "line", "vo_801_lady_sylvanas_windrunner_158_f", "Soldiers, no! Do not rush the..."},
			{2108689, "line", "vo_801_lady_sylvanas_windrunner_159_f", "Ugh, fools! At least now we know how dangerous the wisps can be."},
			{2002709, "line", "vo_801_lady_sylvanas_windrunner_15_f", "The Moon Well Essence should serve you well in battle. Be sure to do the same to any wells the Kaldorei consecrate in the future."},
			{2108690, "line", "vo_801_lady_sylvanas_windrunner_160_f", "Malfurion, how gracious of you to join us."},
			{2108691, "line", "vo_801_lady_sylvanas_windrunner_161_f", "Who would have guessed that you would come to protect your precious trees?"},
			{2108692, "line", "vo_801_lady_sylvanas_windrunner_162_f", "No! My eyes! It burns!"},
			{2108693, "line", "vo_801_lady_sylvanas_windrunner_163_f", "Where did you fly away to, little bird?"},
			{2108694, "line", "vo_801_lady_sylvanas_windrunner_164_f", "Pass through the wall! Quickly! I cannot hold it much longer!"},
			{2108695, "line", "vo_801_lady_sylvanas_windrunner_165_f", "These elementals will serve as fuel for our demolishers. Kill them, as well as any Kaldorei who get in your way."},
			{2108696, "line", "vo_801_lady_sylvanas_windrunner_166_f", "We advance as the fires continue to burn."},
			{2108697, "line", "vo_801_lady_sylvanas_windrunner_167_f", "Look up and around you. The trees have eyes, champion. Blind them."},
			{2108698, "line", "vo_801_lady_sylvanas_windrunner_168_f", "Sofang, it's about time."},
			{2108699, "line", "vo_801_lady_sylvanas_windrunner_169_f", "Look around, you hero. What a lovely sight. The wisps are scattering. One by one, the wall comes crashing down."},
			{2002710, "line", "vo_801_lady_sylvanas_windrunner_16_f", "Alliance saboteurs have infiltrated our foothold. Flush them out. Make them bleed."},
			{2108700, "line", "vo_801_lady_sylvanas_windrunner_170_f", "You"},
			{2108701, "line", "vo_801_lady_sylvanas_windrunner_171_f", "Now is the time. The world tree is ours for the taking. Find Sarfang. We shall finish this once and for all.\""},
			{2108702, "line", "vo_801_lady_sylvanas_windrunner_172_f", "When I sent you on this mission, I did not foresee this outcome."},
			{2108703, "line", "vo_801_lady_sylvanas_windrunner_173_f", "Our attack was meant to end a war before it began, to capture an enemy's home and annihilate their leaders in one stroke, to inflict a wound that would bleed the Alliance dry."},
			{2108704, "line", "vo_801_lady_sylvanas_windrunner_174_f", "We have only partially succeeded. The Alliance will retaliate. They will come for us. For me, for you."},
			{2108705, "line", "vo_801_lady_sylvanas_windrunner_175_f", "But they are bleeding. Their anger will prove a weakness, not a strength, in the war to come."},
			{2108706, "line", "vo_801_lady_sylvanas_windrunner_176_f", "Rest while you can. Prepare for the battles ahead. I will have need of you."},
			{2108707, "line", "vo_801_lady_sylvanas_windrunner_177_f", "Champions of the Horde, your aid is required at Wildbend River. This is our chance for victory!"},
			{2118852, "line", "vo_801_lady_sylvanas_windrunner_178_f", "You"},
			{2118855, "line", "vo_801_lady_sylvanas_windrunner_179_f", "You"},
			{2002711, "line", "vo_801_lady_sylvanas_windrunner_17_f", "Our encampment is secure for now, but remain vigilant."},
			{2120267, "line", "vo_801_lady_sylvanas_windrunner_180_f", "We pass through the wall on my command."},
			{2120268, "line", "vo_801_lady_sylvanas_windrunner_181_f", "Brace yourselves!"},
			{2120269, "line", "vo_801_lady_sylvanas_windrunner_182_f", "You"},
			{2120270, "line", "vo_801_lady_sylvanas_windrunner_183_f", "Once a breach has been made, the pain is bearable. Just give me a moment."},
			{2120591, "line", "vo_801_lady_sylvanas_windrunner_184_f", "My faith in you was well placed. The will of the Kaldorei will soon crumble."},
			{2120594, "line", "vo_801_lady_sylvanas_windrunner_185_f", "The Kaldorei are deadliest in the dark. Jump into the fray and deal with them before night falls."},
			{2125064, "line", "vo_801_lady_sylvanas_windrunner_186_f", "Though our long war against the Legion has ended, the Horde cannot afford a moment of respite."},
			{2126961, "line", "vo_801_lady_sylvanas_windrunner_187_f", "An audience. Perfect. Stay still, Alliance Dog. Watch me strike down one of your greatest heroes."},
			{2131062, "line", "vo_801_lady_sylvanas_windrunner_188_f", "Meet me in my chambers in the Undercity, where we can discuss our next move, discreetly."},
			{2002712, "line", "vo_801_lady_sylvanas_windrunner_18_f", "Azerite powder kegs have been flung from our ships gather them quickly before they sink"},
			{2002713, "line", "vo_801_lady_sylvanas_windrunner_19_f", "Your efforts are needed elsewhere, champion. I have a team of goblins ready to scour for the rest."},
			{2002714, "line", "vo_801_lady_sylvanas_windrunner_20_f", "My Dark Rangers require your help, champion. Lend aid to any that you find."},
			{2002715, "line", "vo_801_lady_sylvanas_windrunner_21_f", "Even with all their training, those dark rangers seem to have miscalculated their attacks. Perhaps Blightcrawler should have words with them."},
			{2002716, "line", "vo_801_lady_sylvanas_windrunner_22_f", "That cargo belongs to the Horde. Do not allow the Alliance to lay their hands upon it."},
			{2002717, "line", "vo_801_lady_sylvanas_windrunner_23_f", "The weapons you reclaimed will prove useful to our war effort, skillfully done."},
			{2002718, "line", "vo_801_lady_sylvanas_windrunner_24_f", "So the ancients decided to come out and play. Let us give them a rude awakening."},
			{2002719, "line", "vo_801_lady_sylvanas_windrunner_25_f", "Imagine, to sleep for thousands of years, only to awaken to defeat, who pathetic."},
			{2002720, "line", "vo_801_lady_sylvanas_windrunner_26_f", "That night elf commander is testing my patience. Break her!"},
			{2002721, "line", "vo_801_lady_sylvanas_windrunner_27_f", "Poor thing. She barely got a chance to swing."},
			{2002722, "line", "vo_801_lady_sylvanas_windrunner_28_f", "Our army has Malfurion soldiers on their heels. We must push further into Darkshore while we hold the advantage."},
			{2002723, "line", "vo_801_lady_sylvanas_windrunner_29_f", "My faith in you was well-placed. The will of the Kaldorei will soon crumble."},
			{2002724, "line", "vo_801_lady_sylvanas_windrunner_30_f", "The Kaldorei are deadliest in the dark. Jump into the fray and deal with them before night falls."},
			{2002726, "line", "vo_801_lady_sylvanas_windrunner_31_f", "We struck a significant blow to their reserves, hero. Well done."},
			{2002727, "line", "vo_801_lady_sylvanas_windrunner_32_f", "Do not relent, hero. These savage elves would do you no such favor."},
			{2002728, "line", "vo_801_lady_sylvanas_windrunner_33_f", "In times of war, you must kill or be killed. There is nothing else to say."},
			{2002729, "line", "vo_801_lady_sylvanas_windrunner_34_f", "The Alliance scours Dark Shore, seeking to root out our footholds. We must not lose ground. Defend what is ours."},
			{2002730, "line", "vo_801_lady_sylvanas_windrunner_35_f", "You fight with finesse, and further, such effort serves to inspire all my soldiers, champion."},
			{2002731, "line", "vo_801_lady_sylvanas_windrunner_36_f", "It seems the Kaldorei have mastered reinforcements. This one may prove to be a challenge. I expect victory."},
			{2002732, "line", "vo_801_lady_sylvanas_windrunner_37_f", "I never doubted you for a moment."},
			{2002733, "line", "vo_801_lady_sylvanas_windrunner_38_f", "Saurfang has crested the mountains between Darkshore and Felwood. Meet him at Shatasphere Vale, and ensure that the passage he seeks is secure."},
			{2002734, "line", "vo_801_lady_sylvanas_windrunner_39_f", "You are the right arrow for the shot, champion."},
			{2002735, "line", "vo_801_lady_sylvanas_windrunner_40_f", "Another Kaldorei commander in the wrong place, at the wrong time. Dispatch her at once, we can't allow her to gather reinforcements."},
			{2002736, "line", "vo_801_lady_sylvanas_windrunner_41_f", "Cut the rose before it can sprout thorns, I always say."},
			{2002737, "line", "vo_801_lady_sylvanas_windrunner_42_f", "Orcs make fine soldiers, but each one eats as much as a dozen goblins. Our food stores need replenishment, mind slaughtering a few beasts while you strike down the Kaldorei?"},
			{2002738, "line", "vo_801_lady_sylvanas_windrunner_43_f", "That should quell their appetites. For a while, at least."},
			{2002739, "line", "vo_801_lady_sylvanas_windrunner_44_f", "An elemental of pure Azerite. Slay it, champion, but do not destroy it. Gather as much of its resin as you can."},
			{2002740, "line", "vo_801_lady_sylvanas_windrunner_45_f", "I have never seen so much Azerite in one place."},
			{2002741, "line", "vo_801_lady_sylvanas_windrunner_46_f", "We have some windriders available to us. Gather our explosives and wreak havoc on that wisp wall. We will send a message to Malfurion."},
			{2002742, "line", "vo_801_lady_sylvanas_windrunner_47_f", "They're not nearly as resilient as they appear, are they, champion? One by one, they fall."},
			{2002743, "line", "vo_801_lady_sylvanas_windrunner_48_f", "The Alliance seeks to use siege weaponry against us? How quaint. Show them what the Horde's demolishers can do."},
			{2002744, "line", "vo_801_lady_sylvanas_windrunner_49_f", "That was a lesson they won't soon forget."},
			{2002745, "line", "vo_801_lady_sylvanas_windrunner_50_f", "Ever use an Azerite Bomb before? Want to witness true power? Brace yourself for Impact Champion. I think you will be pleasantly surprised."},
			{2002746, "line", "vo_801_lady_sylvanas_windrunner_51_f", "All right, that's enough. Let's save some for the grand finale."},
			{2002747, "line", "vo_801_lady_sylvanas_windrunner_52_f", "Forget the army, we can deal with them later! Blast the siege towers!"},
			{2002748, "line", "vo_801_lady_sylvanas_windrunner_53_f", "Do not question me, Saurfang. We must draw their attention from my war machine so it can destroy the towers. Casualties are inevitable."},
			{2002749, "line", "vo_801_lady_sylvanas_windrunner_54_f", "Enough meddling! The towers! The towers!"},
			{2002750, "line", "vo_801_lady_sylvanas_windrunner_55_f", "Ah what have we here? Has the Lion of Stormwind finally come out to play? You have no idea what you're up against, boy king. We have only just begun!"},
			{2002751, "line", "vo_801_lady_sylvanas_windrunner_56_f", "Prepare the blight, let it rain down upon their armies."},
			{2002752, "line", "vo_801_lady_sylvanas_windrunner_57_f", "This is no time for sentiment, High Overlord."},
			{2002753, "line", "vo_801_lady_sylvanas_windrunner_58_f", "War demands that we take a more direct approach."},
			{2002754, "line", "vo_801_lady_sylvanas_windrunner_59_f", "DESTROY THEM!"},
			{2002755, "line", "vo_801_lady_sylvanas_windrunner_60_f", "Bane! Pull them back!"},
			{2002756, "line", "vo_801_lady_sylvanas_windrunner_61_f", "Is the undercity evacuated?"},
			{2002757, "line", "vo_801_lady_sylvanas_windrunner_62_f", "Then it's time to finish this once and for all. Sarfang, rally your troops. I will prepare the Azerite machine."},
			{2002758, "line", "vo_801_lady_sylvanas_windrunner_63_f", "Everyone, move! Cut them off with the reserves. Do not let them pass!"},
			{2002759, "line", "vo_801_lady_sylvanas_windrunner_64_f", "Saurfang, where did you go?"},
			{2002760, "line", "vo_801_lady_sylvanas_windrunner_65_f", "Meet with Lotharmar! Quickly! Do not fail me, Nathanos!"},
			{2002761, "line", "vo_801_lady_sylvanas_windrunner_66_f", "Slay them all, champions! Mark my words. King Anduin and his army did not come here for their amusement. They mean to destroy us. Show them no mercy! For they would show you none in return."},
			{2002762, "line", "vo_801_lady_sylvanas_windrunner_67_f", "You"},
			{2002763, "line", "vo_801_lady_sylvanas_windrunner_68_f", "Everyone! Follow Nathanos to the courtyard! I will block the Alliance from behind!"},
			{2002764, "line", "vo_801_lady_sylvanas_windrunner_69_f", "KEEP MOVING!"},
			{2002765, "line", "vo_801_lady_sylvanas_windrunner_70_f", "We're almost there! Make haste, heroes!"},
			{2002766, "line", "vo_801_lady_sylvanas_windrunner_71_f", "So good of you to finally show up, High Overlord."},
			{2002767, "line", "vo_801_lady_sylvanas_windrunner_72_f", "Honor means nothing to a corpse, Saurfang. You have the luxury of underestimating death, but it is something with which I am intimately familiar."},
			{2002768, "line", "vo_801_lady_sylvanas_windrunner_73_f", "Maybe you don't care if your people die so long as it's honorable, but to me, this horde is worth saving. Anyone who disagrees does not deserve to stand among us."},
			{2002769, "line", "vo_801_lady_sylvanas_windrunner_74_f", "So die your warrior's death, High Overlord Saurfang. It means little to me. Perhaps I will raise your broken body to serve me once more."},
			{2002770, "line", "vo_801_lady_sylvanas_windrunner_75_f", "Or perhaps, you will have a chance to say hello to your son."},
			{2002771, "line", "vo_801_lady_sylvanas_windrunner_76_f", "Champions, with me, you are invited to bear witness to the grand finale."},
			{2002772, "line", "vo_801_lady_sylvanas_windrunner_77_f", "I have taken the liberty of assembling a team for you. Retrieve my prize."},
			{2002773, "line", "vo_801_lady_sylvanas_windrunner_78_f", "Ah, there you are. I was beginning to wonder."},
			{2002774, "line", "vo_801_lady_sylvanas_windrunner_79_f", "I require the services of one whom I can trust completely."},
			{2002775, "line", "vo_801_lady_sylvanas_windrunner_80_f", "Certain members of the Horde seem to feel my recent actions have been indiscriminate."},
			{2002776, "line", "vo_801_lady_sylvanas_windrunner_81_f", "But I understand discretion very well."},
			{2002777, "line", "vo_801_lady_sylvanas_windrunner_82_f", "To win this war, the Horde needs allies."},
			{2002778, "line", "vo_801_lady_sylvanas_windrunner_83_f", "The boy king has something that does not belong to him. I want it back."},
			{2002779, "line", "vo_801_lady_sylvanas_windrunner_84_f", "You are to infiltrate Stormwind and liberate a political prisoner, one who could change the course of the war, in our favor."},
			{2002780, "line", "vo_801_lady_sylvanas_windrunner_85_f", "Are you up to the task?"},
			{2002781, "line", "vo_801_lady_sylvanas_windrunner_86_f", "Oh, I know you won't."},
			{2002782, "line", "vo_801_lady_sylvanas_windrunner_87_f", "Champion, the Horde is now at open war with the Alliance."},
			{2002783, "line", "vo_801_lady_sylvanas_windrunner_88_f", "Our success in this conflict may depend on your skills."},
			{2002784, "line", "vo_801_lady_sylvanas_windrunner_89_f", "I require your immediate presence in Orgrimmar for a mission of the utmost urgency. Do not keep me waiting."},
			{2018551, "line", "vo_801_lady_sylvanas_windrunner_90_f", "You have no idea what you're up against, boy king. We've only just begun."},
			{2020084, "line", "vo_801_lady_sylvanas_windrunner_91_f", "An army of militant orcs from another world, trained its soldiers, weapons waiting to be fixed upon the Alliance, interesting."},
			{2028796, "line", "vo_801_lady_sylvanas_windrunner_92_f", "Farewell, Nathanus."},
			{2029155, "line", "vo_801_lady_sylvanas_windrunner_93_f", "Champions, the hour is at hand. The Alliance shall fall upon our blades as they desperately grasp at our prized Lordaeron keep."},
			{2029156, "line", "vo_801_lady_sylvanas_windrunner_94_f", "Is everything in order?"},
			{2029157, "line", "vo_801_lady_sylvanas_windrunner_95_f", "Good. Work with our champion to determine where we will secure a foothold first."},
			{2029158, "line", "vo_801_lady_sylvanas_windrunner_96_f", "See it done and dispatch reports of your progress to me."},
			{2056427, "line", "vo_801_lady_sylvanas_windrunner_97_f", "Report to High Overlord Saurfang. Teach them the price of their folly. For the Horde!"},
			{2062631, "line", "vo_801_lady_sylvanas_windrunner_98_f", "Champion, when Princess Talonji came to our seeking aid, I recognized an opportunity to add her kingdom's strength to our own."},
			{2062633, "line", "vo_801_lady_sylvanas_windrunner_99_f", "I knew there was no one more capable of winning the Zandalari to our cause than you."},
			{2565373, "line", "vo_815_lady_sylvanas_windrunner_01_f", "I am Sylvanas Windrunner, and I approve this message."},
			{2575528, "line", "vo_815_lady_sylvanas_windrunner_02_f", "Champion, leaders of the Horde, I have summoned you here to discuss matters of war."},
			{2575529, "line", "vo_815_lady_sylvanas_windrunner_03_f", "The Alliance's forces have held strong and show no signs of weakening."},
			{2575530, "line", "vo_815_lady_sylvanas_windrunner_04_f", "Our soldiers grow weary. The Horde's ranks are in need of new blood. What are our options?"},
			{2575531, "line", "vo_815_lady_sylvanas_windrunner_05_f", "We sorely need the Zandalari and their fleet if we intend to engage the Alliance again."},
			{2575606, "line", "vo_815_lady_sylvanas_windrunner_06_f", "She thinks to summon me. I suppose she has allowed some posturing today."},
			{2575607, "line", "vo_815_lady_sylvanas_windrunner_07_f", "Congratulations, Your Majesty."},
			{2575609, "line", "vo_815_lady_sylvanas_windrunner_08_f", "Yes, it is beyond time we did."},
			{2575614, "line", "vo_815_lady_sylvanas_windrunner_09_f", "equals"},
			{2575616, "line", "vo_815_lady_sylvanas_windrunner_10_f", "I see. Very well. Queen Talandri. The Horde welcomes you."},
			{2575617, "line", "vo_815_lady_sylvanas_windrunner_11_f", "You have performed admirably. Arrangements will be made to greet our new allies in Orgrimmar."},
			{2699025, "line", "vo_815_lady_sylvanas_windrunner_12_f", "The Alliance believes that by striking down Rastakhan and decimating the Zandalari fleet, they have broken us. That the Horde will soon crumble."},
			{2699026, "line", "vo_815_lady_sylvanas_windrunner_13_f", "Fools. The boy king has lied to himself and his people. He hasn't the faintest inkling of what he's truly up against."},
			{2699027, "line", "vo_815_lady_sylvanas_windrunner_14_f", "War is a living thing. It arrives, it grows, twisting and turning until its final form is revealed."},
			{2699028, "line", "vo_815_lady_sylvanas_windrunner_15_f", "This war is about to shift yet again, and it will be this blade that guides our way to victory."},
			{2736326, "line", "vo_815_lady_sylvanas_windrunner_16_f", "I have troubling news."},
			{2736327, "line", "vo_815_lady_sylvanas_windrunner_17_f", "Most of you need fear nothing."},
			{2736328, "line", "vo_815_lady_sylvanas_windrunner_18_f", "But Derek Proudmoore didn't flee to Kul Tiras by himself."},
			{2736329, "line", "vo_815_lady_sylvanas_windrunner_19_f", "Zelling"},
			{2736330, "line", "vo_815_lady_sylvanas_windrunner_20_f", "Thank you for your honesty."},
			{2736331, "line", "vo_815_lady_sylvanas_windrunner_21_f", "No. He did. And so did you."},
			{2736332, "line", "vo_815_lady_sylvanas_windrunner_22_f", "Take him!"},
			{2736333, "line", "vo_815_lady_sylvanas_windrunner_23_f", "There is no place for weakness in our ranks."},
			{2736334, "line", "vo_815_lady_sylvanas_windrunner_24_f", "Remember your loyalties."},
			{2737052, "line", "vo_815_lady_sylvanas_windrunner_25_f", "Zalatoth, a fascinating weapon. I have heard tales of its exploits."},
			{2737053, "line", "vo_815_lady_sylvanas_windrunner_26_f", "A pity now lies dormant, but anything that slumbers can be awakened."},
			{2737054, "line", "vo_815_lady_sylvanas_windrunner_27_f", "This blade is more than a mere dagger. It is a torch that shall light our path forward."},
			{2737055, "line", "vo_815_lady_sylvanas_windrunner_28_f", "Soon I will call upon you again, champion, and together we will steer the Horde toward its destiny."},
			{2764308, "line", "vo_815_lady_sylvanas_windrunner_29_f", "It seems there are traitors in our midst."},
			{2764309, "line", "vo_815_lady_sylvanas_windrunner_30_f", "He had help, didn't he?"},
			{2407031, "line", "vo_81_lady_sylvanas_windrunner_01_f", "Thank you for coming so quickly, champion. This is a matter I could entrust only to you."},
			{2407032, "line", "vo_81_lady_sylvanas_windrunner_02_f", "My spies report that Varok Sarfang has escaped Alliance custody. He'd been held in the Stormwinds' arcades since the assault on Lordaeron."},
			{2407033, "line", "vo_81_lady_sylvanas_windrunner_03_f", "Should the boy king's forces locate Sarfang, no doubt they will kill him on sight."},
			{2407034, "line", "vo_81_lady_sylvanas_windrunner_04_f", "While some within our ranks have questioned the High Overlord's loyalties, we cannot allow him to fall back into enemy hands."},
			{2407035, "line", "vo_81_lady_sylvanas_windrunner_05_f", "I expect you to find him before they do."},
			{2407036, "line", "vo_81_lady_sylvanas_windrunner_06_f", "Dark Ranger Lyanna is an exceptional tracker. She will assist you on this assignment."},
			{2407038, "line", "vo_81_lady_sylvanas_windrunner_07_f", "Good hunting, champion."},
			{2407228, "line", "vo_81_lady_sylvanas_windrunner_08_f", "Let me see if I have this right. Saurfang single-handedly slew my elite forces and a veteran Dark Ranger?"},
			{2407229, "line", "vo_81_lady_sylvanas_windrunner_09_f", "How fortunate that you escaped with little more than a bruise. Fortunate, but disappointing."},
			{2407230, "line", "vo_81_lady_sylvanas_windrunner_10_f", "Let me be perfectly clear. You will find the traitor Saurfang. You will deliver him to me. And you will not fail me again."},
			{2407231, "line", "vo_81_lady_sylvanas_windrunner_11_f", "Now go. Remember your duty to the Horde. We have a war to win."},
			{2429529, "line", "vo_81_lady_sylvanas_windrunner_12_f", "Derek Proudmoore was a hero to the Kulturans."},
			{2429530, "line", "vo_81_lady_sylvanas_windrunner_13_f", "They are sure to stage a rescue attempt when they learn of his fate."},
			{2429531, "line", "vo_81_lady_sylvanas_windrunner_14_f", "And once his mind has been properly conditioned, we will allow the Proud Moors to recover their long-lost prince."},
			{2429532, "line", "vo_81_lady_sylvanas_windrunner_15_f", "so he can slaughter them in their sleep."},
			{2429533, "line", "vo_81_lady_sylvanas_windrunner_16_f", "There can only be victory or death for us, Spain."},
			{2429534, "line", "vo_81_lady_sylvanas_windrunner_17_f", "And death is mine to master."},
			{2429535, "line", "vo_81_lady_sylvanas_windrunner_18_f", "Why, Lord Proudmoore, I've given you a chance to reunite with your family."},
			{2429536, "line", "vo_81_lady_sylvanas_windrunner_19_f", "You should be grateful."},
			{2443805, "line", "vo_81_lady_sylvanas_windrunner_20_f", "You there, fast rider, man or ballista, provide cover for the retreating civilians."},
			{2443806, "line", "vo_81_lady_sylvanas_windrunner_21_f", "Behold the fruit of your labors, Derek Proudmoore, the corpse you recovered from the depths of the sea."},
			{2443807, "line", "vo_81_lady_sylvanas_windrunner_22_f", "It shall prove a valuable weapon in our war against Kul Tiras, a dagger, to plunge into the very heart of House Proudmoore, when the time is right."},
			{2443808, "line", "vo_81_lady_sylvanas_windrunner_23_f", "And thanks to your efforts, the Horde has secured the might of the Zandalari fleet. All that remains is to finish breaking our foes. Then, we will have victory in this war."},
			{2443809, "line", "vo_81_lady_sylvanas_windrunner_24_f", "Very perceptive, Lady Ashvane. I believe we have mutual interests to discuss."},
			{2443810, "line", "vo_81_lady_sylvanas_windrunner_25_f", "My condolence is on your lost princess. Excuse me, Queen Talanji."},
			{2443811, "line", "vo_81_lady_sylvanas_windrunner_26_f", "We do not turn our back on our allies, Talanji. The war campaign has taken an unfortunate turn to be certain, but our cause is not lost."},
			{2443812, "line", "vo_81_lady_sylvanas_windrunner_27_f", "The Alliance slays the leader of the Zandalari, and you speak of negotiations?"},
			{2443813, "line", "vo_81_lady_sylvanas_windrunner_28_f", "No, this war will not end until we stand victorious. Until the little lion kneels before my throne."},
			{2443814, "line", "vo_81_lady_sylvanas_windrunner_29_f", "Meet me aboard the banshee's wail. I have a plan to ensure the Proudmoore family pays dearly for Rastakhan's death."},
			{2907627, "line", "vo_825_lady_sylvanas_windrunner_01_f", "You"},
			{2907628, "line", "vo_825_lady_sylvanas_windrunner_02_f", "You"},
			{2907629, "line", "vo_825_lady_sylvanas_windrunner_03_f", "You"},
			{3049143, "line", "vo_825_lady_sylvanas_windrunner_04_f_rtc", "Ah, champion, I wasn't certain you made it out of ogremont. If the traitors knew of your service to me, they'd have put you in irons."},
			{3049144, "line", "vo_825_lady_sylvanas_windrunner_05_f_rtc", "Sarfang's ill-considered challenge may have ended the war prematurely, but it doesn't matter now."},
			{3049145, "line", "vo_825_lady_sylvanas_windrunner_06_f_rtc", "Countless souls have been fed to the hungering darkness."},
			{3049146, "line", "vo_825_lady_sylvanas_windrunner_07_f_rtc", "Though I cared nothing for the living, I did pity the Forsaken for the great injustice that made them what they are."},
			{3049147, "line", "vo_825_lady_sylvanas_windrunner_08_f_rtc", "But despite all I taught them, they stubbornly clung to hope, to life."},
			{3049148, "line", "vo_825_lady_sylvanas_windrunner_09_f_rtc", "My bargain with Azshara will yet bear fruit. The armies of Azeroth will fight her master, and he will line their streets with corpses."},
			{3049149, "line", "vo_825_lady_sylvanas_windrunner_10_f_rtc", "Enough reflection. There are preparations to be made."},
			{3049150, "line", "vo_825_lady_sylvanas_windrunner_11_f", "You"},
			{3049151, "line", "vo_825_lady_sylvanas_windrunner_12_f_rtc", "Nothing lasts."},
			{3049409, "line", "vo_825_lady_sylvanas_windrunner_13_f", "There won't be, safe journey, not found out."},
			{3052352, "line", "vo_825_lady_sylvanas_windrunner_14_f", "Ah, champion, ever the loyal soldier."},
			{3052353, "line", "vo_825_lady_sylvanas_windrunner_15_f", "My Dark Rangers have vital information to share with you."},
			{3052354, "line", "vo_825_lady_sylvanas_windrunner_16_f", "Report to Nathanos once you have rallied our forces. There remains much to do."},
			{3052355, "line", "vo_825_lady_sylvanas_windrunner_17_f", "We will grind these traitors into dust. Your loyalty will be rewarded."},
			{3084073, "line", "vo_825_lady_sylvanas_windrunner_18_f_rtc", "Oh, worse."},
			{3084076, "line", "vo_825_lady_sylvanas_windrunner_19_f_rtc", "I understand the cruelty of fate better than anyone."},
			{3084079, "line", "vo_825_lady_sylvanas_windrunner_20_f_rtc", "They will learn the truth, along with all the rest."},
			{3084082, "line", "vo_825_lady_sylvanas_windrunner_21_f_rtc", "In the end, he too will serve death."},
			{3084085, "line", "vo_825_lady_sylvanas_windrunner_22_f_rtc", "When next you see me, you will understand."},
			{2844686, "line", "vo_82_lady_sylvanas_windrunner_01_f", "You"},
			{2844687, "line", "vo_82_lady_sylvanas_windrunner_02_f", "You"},
			{2844688, "line", "vo_82_lady_sylvanas_windrunner_03_f", "You"},
			{2921251, "line", "vo_82_lady_sylvanas_windrunner_04_f", "Enough!"},
			{2921252, "line", "vo_82_lady_sylvanas_windrunner_05_f", "Let's see how brave Gilneas gets on without its stubborn leader."},
			{2921253, "line", "vo_82_lady_sylvanas_windrunner_06_f", "Such a waste. That arrow's poison was not meant to be wasted on your whelp. We'll meet again, Greymane."},
			{2976145, "line", "vo_82_lady_sylvanas_windrunner_07_f", "Nathanos, the next phase of our campaign is at hand."},
			{2976146, "line", "vo_82_lady_sylvanas_windrunner_08_f", "Sail out with what remains of our fleet. The blade will guide you to the rendezvous."},
			{2976147, "line", "vo_82_lady_sylvanas_windrunner_09_f", "Casualties on both sides will be substantial. Consider this an opportunity to weed out the disloyal."},
			{2976148, "line", "vo_82_lady_sylvanas_windrunner_10_f", "The threads we have woven with such care will soon be drawn together. The war is serving its purpose. Stay focused on the endgame. You know what is to come."},
			{2976149, "line", "vo_82_lady_sylvanas_windrunner_11_f", "We have been through so much together, you and I. Trust in me as I have ever trusted in you."},
			{3166448, "line", "vo_835_lady_sylvanas_windrunner_01_f", "And in turn, you will have the key required to free the old god from his bonds and leave him vulnerable."},
			{3166450, "line", "vo_835_lady_sylvanas_windrunner_02_f", "Indeed. Just to be certain that once you have what you need, you dispose of your guests. Let none of the heroes escape."},
			{3166452, "line", "vo_835_lady_sylvanas_windrunner_03_f", "at present."},
			{2844677, "line", "vo_83_lady_sylvanas_windrunner_01_f", "You"},
			{2844678, "line", "vo_83_lady_sylvanas_windrunner_02_f", "You"},
			{2844679, "line", "vo_83_lady_sylvanas_windrunner_03_f", "You"},
			{3587734, "line", "vo_901_lady_sylvanas_windrunner_01_f", "It seems you have an eye for talent, Warlord Grimax."},
			{3587735, "line", "vo_901_lady_sylvanas_windrunner_02_f", "Your skills come highly recommended. I will make use of them."},
			{3587736, "line", "vo_901_lady_sylvanas_windrunner_03_f", "To ensure our victory over the Alliance, the Horde must add strength to its ranks."},
			{3587737, "line", "vo_901_lady_sylvanas_windrunner_04_f", "The boy king of Stormwind has taken a valuable prisoner who may provide us with the allies we need."},
			{3587738, "line", "vo_901_lady_sylvanas_windrunner_05_f", "My champion, Nathanos Blightcaller, is assembling a team to infiltrate Stormwind and liberate our prize. You will join him."},
			{3587739, "line", "vo_901_lady_sylvanas_windrunner_06_f", "Nathanos, brief our new arrival on the mission at hand."},
			{3587740, "line", "vo_901_lady_sylvanas_windrunner_07_f", "I am certain you won't."},
			{3698368, "line", "vo_901_lady_sylvanas_windrunner_08_f", "such a narrow vision you disappoint me"},
			{3698369, "line", "vo_901_lady_sylvanas_windrunner_09_f", "No matter, we will find what we seek in another."},
			{3723893, "line", "vo_901_lady_sylvanas_windrunner_10_f", "Leave him to me. You've seen what he is capable of when he believes in the cause. A measure of patience may yield superior results."},
			{3723910, "line", "vo_901_lady_sylvanas_windrunner_11_f", "You"},
			{4177769, "line", "vo_915_banshee_sylvanas_no_loc_01_f", "You"},
			{4177770, "line", "vo_915_banshee_sylvanas_no_loc_02_f", "You"},
			{4177771, "line", "vo_915_banshee_sylvanas_no_loc_03_f", "You"},
			{4177772, "line", "vo_915_banshee_sylvanas_no_loc_04_f", "You"},
			{4177773, "line", "vo_915_banshee_sylvanas_no_loc_05_f", "You"},
			{4177774, "line", "vo_915_banshee_sylvanas_no_loc_06_f", "You"},
			{4177775, "line", "vo_915_banshee_sylvanas_no_loc_07_f", "You"},
			{4177776, "line", "vo_915_banshee_sylvanas_no_loc_08_f", "You"},
			{4177777, "line", "vo_915_banshee_sylvanas_no_loc_09_f", "You"},
			{4066467, "line", "vo_91_lady_sylvanas_windrunner_01_f", "An illusion. So the Winter Queen sends her loyal subjects to die in her place."},
			{4066473, "line", "vo_91_lady_sylvanas_windrunner_02_f", "It is you who knows nothing, Fae. You cannot stop what is to come."},
			{4075660, "line", "vo_91_lady_sylvanas_windrunner_03_f", "I will deal with the invading forces atop Torghast."},
			{4075661, "line", "vo_91_lady_sylvanas_windrunner_04_f", "The battle is almost upon us."},
			{4075662, "line", "vo_91_lady_sylvanas_windrunner_05_f", "When we reach Oribos, you will defend Zovaal while he completes the ritual."},
			{4075663, "line", "vo_91_lady_sylvanas_windrunner_06_f", "Yes, young lion, but in the end, the sacrifices we've made will have been worth it."},
			{4075664, "line", "vo_91_lady_sylvanas_windrunner_07_f", "Once the cycle of life and death has been broken and remade, we will..."},
			{4080409, "line", "vo_91_lady_sylvanas_windrunner_08_f", "All forces forward! Find the Winter Queen so I can claim that sigil!"},
			{4080410, "line", "vo_91_lady_sylvanas_windrunner_09_f", "Well..."},
			{4080411, "line", "vo_91_lady_sylvanas_windrunner_10_f", "So Azeroth's hero has come to play. You will fail yet again."},
			{4080412, "line", "vo_91_lady_sylvanas_windrunner_11_f", "You were loyal, once. You should know better than to interfere with me."},
			{4080413, "line", "vo_91_lady_sylvanas_windrunner_12_f", "You are wise to show restraint, but it changes nothing."},
			{4080414, "line", "vo_91_lady_sylvanas_windrunner_13_f", "To the skies, strike at the heart!"},
			{4080415, "line", "vo_91_lady_sylvanas_windrunner_14_f", "You are willing to sacrifice your servants, but what of the spirits in your charge?"},
			{4080416, "line", "vo_91_lady_sylvanas_windrunner_15_f", "Surrender your sigil or the wildseeds will perish."},
			{4080417, "line", "vo_91_lady_sylvanas_windrunner_16_f", "Pitiful fae, you've already lost!"},
			{4080418, "line", "vo_91_lady_sylvanas_windrunner_17_f", "This ends now."},
			{4081135, "line", "vo_91_lady_sylvanas_windrunner_18_f", "Heed the call of the Banshee Queen!"},
			{4081136, "line", "vo_91_lady_sylvanas_windrunner_19_f", "Hear my cry, and despair."},
			{4081137, "line", "vo_91_lady_sylvanas_windrunner_20_f", "Death awaits you!"},
			{4081138, "line", "vo_91_lady_sylvanas_windrunner_21_f", "Your lives end here!"},
			{4081139, "line", "vo_91_lady_sylvanas_windrunner_22_f", "Hear the sound of suffering!"},
			{4081140, "line", "vo_91_lady_sylvanas_windrunner_23_f", "Nothing escapes my wrath."},
			{4081141, "line", "vo_91_lady_sylvanas_windrunner_24_f", "All hope is lost."},
			{4081142, "line", "vo_91_lady_sylvanas_windrunner_25_f", "darkness take you"},
			{4081159, "line", "vo_91_lady_sylvanas_windrunner_26_f", "In death you will serve!"},
			{4081160, "line", "vo_91_lady_sylvanas_windrunner_27_f", "Death bends to my will!"},
			{4081161, "line", "vo_91_lady_sylvanas_windrunner_28_f", "The past shackles you!"},
			{4081162, "line", "vo_91_lady_sylvanas_windrunner_29_f", "You are unfit to stand against me!"},
			{4081163, "line", "vo_91_lady_sylvanas_windrunner_30_f", "Suffer my wrath!"},
			{4081164, "line", "vo_91_lady_sylvanas_windrunner_31_f", "Fall into oblivion!"},
			{4081165, "line", "vo_91_lady_sylvanas_windrunner_32_f", "Zovaal will not be denied!"},
			{4081166, "line", "vo_91_lady_sylvanas_windrunner_33_f", "A new age beckons, but you are unworthy of a place in it."},
			{4081167, "line", "vo_91_lady_sylvanas_windrunner_34_f", "Enough! Your resistance ends here!"},
			{4081168, "line", "vo_91_lady_sylvanas_windrunner_35_f", "The maw devours everything!"},
			{4081169, "line", "vo_91_lady_sylvanas_windrunner_36_f", "The maw will claim you!"},
			{4081170, "line", "vo_91_lady_sylvanas_windrunner_37_f", "Do you fear the shadows?"},
			{4081171, "line", "vo_91_lady_sylvanas_windrunner_38_f", "Shadows draw near."},
			{4081772, "line", "vo_91_lady_sylvanas_windrunner_39_f", "I always hit my mark."},
			{4081773, "line", "vo_91_lady_sylvanas_windrunner_40_f", "No mercy!"},
			{4081774, "line", "vo_91_lady_sylvanas_windrunner_41_f", "Vengeance is mine!"},
			{4081775, "line", "vo_91_lady_sylvanas_windrunner_42_f", "TO THE DEATH!"},
			{4081776, "line", "vo_91_lady_sylvanas_windrunner_43_f", "I never miss!"},
			{4081777, "line", "vo_91_lady_sylvanas_windrunner_44_f", "Very well. Death it is!"},
			{4082289, "line", "vo_91_lady_sylvanas_windrunner_45_f", "The cycle will be broken. At long last, we will have justice."},
			{4082343, "line", "vo_91_lady_sylvanas_windrunner_46_f", "FALL HERO!"},
			{4082344, "line", "vo_91_lady_sylvanas_windrunner_47_f", "Feel for the maw!"},
			{4082345, "line", "vo_91_lady_sylvanas_windrunner_48_f", "You always were weak."},
			{4082358, "line", "vo_91_lady_sylvanas_windrunner_49_f", "I shattered your throne, now I'll break you."},
			{4082359, "line", "vo_91_lady_sylvanas_windrunner_50_f", "You will pay! All of you will pay!"},
			{4093247, "line", "vo_91_lady_sylvanas_windrunner_51_f", "Fools! You fight a battle you cannot win!"},
			{4093248, "line", "vo_91_lady_sylvanas_windrunner_52_f", "Four Dragon, a fallen king without a throne. You will answer for your defiance."},
			{4093249, "line", "vo_91_lady_sylvanas_windrunner_53_f", "Valkyr, you are bound to me. Strike down my foes."},
			{4093250, "line", "vo_91_lady_sylvanas_windrunner_54_f", "Azeroth's champions, you've arrived at last."},
			{4093251, "line", "vo_91_lady_sylvanas_windrunner_55_f", "The archer does not mourn the loss of their arrows, high lord."},
			{4093252, "line", "vo_91_lady_sylvanas_windrunner_56_f", "A shame you won't survive to witness our victory. But if it's an ending you seek, then come and meet it."},
			{4093461, "line", "vo_91_lady_sylvanas_windrunner_57_f", "Despite witnessing the broken cycle of life and death with your own eyes, still, you would stop us from remaking this flawed system. What a pity."},
			{4322887, "line", "vo_920_sylvanas_01", "I will face whatever comes."},
			{4322888, "line", "vo_920_sylvanas_02", "The cycle must be broken."},
			{4322889, "line", "vo_920_sylvanas_03", "We are more than slaves to our torments."},
			{4322890, "line", "vo_920_sylvanas_04", "Farewell."},
			{4322891, "line", "vo_920_sylvanas_05", "The true battle lies ahead."},
			{4322892, "line", "vo_920_sylvanas_06", "I found you before my love, I will find you again, no matter how long it takes."},
			{4322893, "line", "vo_920_sylvanas_07", "I will never serve."},
			{4322895, "line", "vo_920_sylvanas_08", "We live in prisons of our own making."},
			{4322896, "line", "vo_920_sylvanas_09", "Not a banshee queen, not a ranger general, but always a windrunner."},
			{4324001, "line", "vo_920_sylvanas_10", "The jailer did not control me."},
			{4324002, "line", "vo_920_sylvanas_11", "Death would be a merciful end, Tyrande."},
			{4324003, "line", "vo_920_sylvanas_12", "however long it takes."},
			{4324058, "line", "vo_920_sylvanas_13", "This is a perilous undertaking, Kyrium. Domination magic is not easy to overcome."},
			{4324103, "line", "vo_920_sylvanas_14", "I see your struggle, young lion. Allow me to offer perspective."},
			{4324115, "line", "vo_920_sylvanas_15", "This is not the end of your suffering, but it is a step forward."},
			{4324121, "line", "vo_920_sylvanas_16", "Let us be done with this."},
			{4324134, "line", "vo_920_sylvanas_17", "Never again will a Lich King reign in Icecrown."},
			{4324488, "line", "vo_920_sylvanas_18", "I expect no less."},
			{4324499, "line", "vo_920_sylvanas_19", "Anger and pain make it difficult to tell the difference."},
			{4324516, "line", "vo_920_sylvanas_20", "I know, sisters, but judgment comes."},
			{4324764, "line", "vo_920_sylvanas_21", "The jailer is using Anduin to bolster his ranks."},
			{4325055, "line", "vo_920_sylvanas_22", "Our only hope is that Anduin's will proves stronger."},
			{4325683, "line", "vo_920_sylvanas_23", "You need time to recover, but we must press on. Lajela has reached the final chamber of the Sepulchre. He is perilously close to victory."},
			{4325704, "line", "vo_920_sylvanas_24", "If you find yourself turning that axe against your allies, you'll have your answer."},
			{4326948, "line", "vo_920_sylvanas_25", "Break his hold and win. The strength lies within you!"},
			{4327507, "line", "vo_920_sylvanas_26", "I don't remember the exact moment I rested, Control."},
			{4327508, "line", "vo_920_sylvanas_27", "I do remember the rush of freedom, the clarity of purpose."},
			{4327509, "line", "vo_920_sylvanas_28", "When I loosed my arrow, I sought to become his judge and his executioner."},
			{4327510, "line", "vo_920_sylvanas_29", "I thought that if I could punish him for his crimes, I would be absolved of mine."},
			{4327511, "line", "vo_920_sylvanas_30", "Forgive him for the atrocities he forced me to commit against my own people."},
			{4327512, "line", "vo_920_sylvanas_31", "But there would be no justice that day."},
			{4327513, "line", "vo_920_sylvanas_32", "for anyone."},
			{4327514, "line", "vo_920_sylvanas_33", "That is yet to come."},
			{4329609, "line", "vo_920_sylvanas_34", "And if the jailer has breached the Sepulchre, then he is but a breath away from enacting his plan."},
			{4329612, "line", "vo_920_sylvanas_35", "You all have witnessed the Jailer's power first hand, without the means to resist his domination. We have no chance against him."},
			{4329613, "line", "vo_920_sylvanas_36", "Anduin may be the key, if we can save him from."},
			{4330819, "line", "vo_920_sylvanas_37", "My actions were mine alone, and I accept their consequences."},
			{4330822, "line", "vo_920_sylvanas_38", "And I do not expect your mercy."},
			{4383680, "line", "vo_920_sylvanas_39", "I submit to the judgment."},
			{4383683, "line", "vo_920_sylvanas_40", "of Tyrande Whisperwind."},
			{4496030, "line", "vo_925_lady_sylvanas_windrunner_01_f", "Why are you here, Anduan?"},
			{4496031, "line", "vo_925_lady_sylvanas_windrunner_02_f", "Your kingdom and your friends are awaiting your return."},
			{4496032, "line", "vo_925_lady_sylvanas_windrunner_03_f", "It is perilous to confuse what you are made to do with what you choose to do."},
			{4496033, "line", "vo_925_lady_sylvanas_windrunner_04_f", "Ah, so that's why you've come."},
			{4496034, "line", "vo_925_lady_sylvanas_windrunner_05_f", "You fear you might not be who you thought you were."},
			{4496035, "line", "vo_925_lady_sylvanas_windrunner_06_f", "Must you bear that weight?"},
			{4496036, "line", "vo_925_lady_sylvanas_windrunner_07_f", "No choice."},
			{4496037, "line", "vo_925_lady_sylvanas_windrunner_08_f", "I thought you believed in free will."},
			{4496038, "line", "vo_925_lady_sylvanas_windrunner_09_f", "I have faced who I was and accepted what I've done."},
			{4496039, "line", "vo_925_lady_sylvanas_windrunner_10_f", "Now the work begins."},
			{4496040, "line", "vo_925_lady_sylvanas_windrunner_11_f", "Farewell, Little Lion."},
			{4509388, "line", "vo_925_lady_sylvanas_windrunner_12_f", "And one."},
			{4332018, "line", "vo_92_lady_sylvanas_windrunner_40_f", "It shall be done."},
			{573174, "line", "vo_et_echoofsylvanas_reset_01", "And so ends your story."},
			{573176, "line", "vo_et_echoofsylvanas_slay_01", "Cry Havoc!"},
			{573178, "line", "vo_et_echoofsylvanas_spell_01", "Watch heathens as death surrounds you."},
			{573180, "line", "vo_et_echoofsylvanas_spell_02", "AHHHHHHHHHH"},
			{561274, "line", "vo_qe_sp_sylvanas_gievent01", "ENOUGH!"},
			{561261, "line", "vo_qe_sp_sylvanas_gievent02", "Such a waste! That arrow's poison was not meant to be spent on your whelp! We will meet again!"},
			{561269, "line", "vo_qe_sp_sylvanas_spevent01", "Where is that ogre-headed buffoon?"},
			{561224, "line", "vo_qe_sp_sylvanas_spevent02", "Ah, speak of the devil."},
			{561229, "line", "vo_qe_sp_sylvanas_spevent03", "Warchief! So glad you could make it!"},
			{561221, "line", "vo_qe_sp_sylvanas_spevent04", "With the death of the Lich King, many of the more intelligent Scourge became… unemployed. Those fiends, as you so delicately put it, are called Valkyr. They are under my command now."},
			{561251, "line", "vo_qe_sp_sylvanas_spevent05", "And they are part of the reason that I asked to see you."},
			{561263, "line", "vo_qe_sp_sylvanas_spevent06", "Very well, Warchief. I have solved the plight of the Forsaken."},
			{561262, "line", "vo_qe_sp_sylvanas_spevent07", "As a race, we forsaken our unable to procreate."},
			{561253, "line", "vo_qe_sp_sylvanas_spevent08", "With the aid of the Valkyr, we are now able to take the corpses of the fallen and create new forsaken."},
			{561255, "line", "vo_qe_sp_sylvanas_spevent09", "Agatha, show the warchief!"},
			{561257, "line", "vo_qe_sp_sylvanas_spevent10", "Warchief, without these new forsaken, my people would die out. Our hold upon Gilneas and Northern Lordaeron would crumble."},
			{561239, "line", "vo_qe_sp_sylvanas_spevent11", "Isn't it obvious, Warchief? I serve the Horde."},
			{561232, "line", "vo_qe_sylvanas_event01", "I have not always been the Banshee Queen."},
			{561244, "line", "vo_qe_sylvanas_event02", "And my people have not always been the Forsaken."},
			{561245, "line", "vo_qe_sylvanas_event03", "Long ago, this land comprised the northern kingdoms of Lordaeron, ruled by King Terenas Menethil."},
			{561222, "line", "vo_qe_sylvanas_event04", "Terenas had a son named Arthas."},
			{561236, "line", "vo_qe_sylvanas_event05", "Arthas, even saying his name makes my body quiver in rage."},
			{561264, "line", "vo_qe_sylvanas_event06", "This man-child, Arthas, took for himself a cursed blade known as Frostmourne."},
			{561235, "line", "vo_qe_sylvanas_event07", "Through Frostmourne, Arthas killed his own father and raised this land along with every living creature in it."},
			{561237, "line", "vo_qe_sylvanas_event08", "My own death came at the hands of Arthas when he and his armies sacked my homeland, Quel'Thalos, and murdered my people."},
			{561247, "line", "vo_qe_sylvanas_event09", "In his vast cruelty, Arthas severed my spirit from my body and raised me as a banshee to serve in his scourge army."},
			{561275, "line", "vo_qe_sylvanas_event10", "A similar fate befell all that would die to the Scourge war machine."},
			{561246, "line", "vo_qe_sylvanas_event11", "In death, they were reborn as mindless undead."},
			{561259, "line", "vo_qe_sylvanas_event12", "But Arthas was not invincible. With each passing day his power waned, his grip over the will of the damned loosening."},
			{561223, "line", "vo_qe_sylvanas_event13", "It was when Arthas was at his weakest that I struck."},
			{561252, "line", "vo_qe_sylvanas_event14", "And though the hour of his atonement had come, the worm managed to escape his fate, returning to the frozen wastes of Northrend."},
			{561276, "line", "vo_qe_sylvanas_event15", "With Arthas gone, so too was the control he held over the undead masses of Lordaeron. After recovering my body, I freed the remaining scourge that were left behind."},
			{561234, "line", "vo_qe_sylvanas_event16", "From the cruelty and mercilessness of Arthas, the man who would be Lich King, the Forsaken were born."},
			{561228, "line", "vo_qe_sylvanas_event17", "Our goal, our sole purpose, was to destroy the Lich King. We threw our lot in with the Horde and began our journey towards redemption."},
			{561249, "line", "vo_qe_sylvanas_event18", "Now, the Lich King is dead, and we have returned."},
			{561270, "line", "vo_qe_sylvanas_event19", "The people who called this land their home in life do so in death as well."},
			{561243, "line", "vo_qe_sylvanas_event20", "But the Alliance does not recognize our rights. They claim this land is their own while attempting to invalidate the claims of the founders of this kingdom."},
			{561267, "line", "vo_qe_sylvanas_event21", "I will never allow it! Never!"},
			{561272, "line", "vo_qe_sylvanas_event22", "Lordaeron belongs to the Forsaken, always and forever."},
			{561238, "line", "vo_qe_sylvanas_hunt01", "You can assure Garrosh that this is a minor setback. Our victory in Gelneus will be absolute."},
			{561250, "line", "vo_qe_sylvanas_hunt02", "You'd do well to watch your tone, General. Neither you nor Garrosh have anything to worry about. We've ceased all production of the Plague, as he ordered. We'd never deploy it without his permission."},
			{561273, "line", "vo_qe_sylvanas_hunt03", "Go with honor, General."},
			{561248, "line", "vo_qe_sylvanas_hunt04", "What kind of question is that? Of course we're deploying the plague, as planned. Let the Gilneans enjoy their small victory. Not even their bones will remain by tomorrow."},
			{561233, "line", "vo_sylvanas_wickerman_event_01", "Children of the Grave, heed my call!"},
			{561219, "line", "vo_sylvanas_wickerman_event_02", "In life, we suffered unspeakable tragedies."},
			{561258, "line", "vo_sylvanas_wickerman_event_03", "We watched as our homes were raised to the ground."},
			{561266, "line", "vo_sylvanas_wickerman_event_04", "We cried out in agony, and our families were cut down before our eyes."},
			{561254, "line", "vo_sylvanas_wickerman_event_05", "Finally, in the face of such atrocities, we were denied even the release of DEATH!"},
			{561260, "line", "vo_sylvanas_wickerman_event_06", "Now, we burn this Wicker Man as a symbol of our victory against old enemies."},
			{561227, "line", "vo_sylvanas_wickerman_event_07", "We paint our faces with the ash to send a message to new enemies, a declaration to those who fear and revile us as monsters."},
			{561226, "line", "vo_sylvanas_wickerman_event_08", "To those who would question our place in this world!"},
			{561218, "line", "vo_sylvanas_wickerman_event_09", "We are not monsters! We are not the mindless wretches of Ghoul Army!"},
			{561240, "line", "vo_sylvanas_wickerman_event_10", "No! We are a force even more terrifying!"},
			{561220, "line", "vo_sylvanas_wickerman_event_11", "We are a shell in a coward's spine."},
			{561265, "line", "vo_sylvanas_wickerman_event_12", "We are the instruments of the unyielding Aya!"},
			{561271, "line", "vo_sylvanas_wickerman_event_13", "We are the Forsaken!"},
		},
