	[7] = {
		voice = {
			{545807, "pick", "cairnebloodhoofgreeting01", "Take heart, young one. The Earth Mother is near."},
			{545805, "pick", "cairnebloodhoofgreeting02", "Ishmaelu Pora! May the Earthmother smile upon you."},
			{545808, "pick", "cairnebloodhoofgreeting03", "I am Cairne, Chief of the Bloodhoof Tauren."},
			{545806, "pick", "cairnebloodhoofgreeting04", "We, Torrin, have always held a great respect for the works of the Earth Mother."},
			{2911901, "pick", "vo_82_cairne_bloodhoof_02_m", "Our way seeks not destruction, but harmony. We need both light and shadow to see what lies before us."},
			{2911905, "pick", "vo_82_cairne_bloodhoof_05_m", "We are proud of you, my son. Remember always that the Earth Mother watches over you. And so do we."},
			{545804, "aggro", "cairnebloodhoofaggro01", "I'S NAOLO PORA!"},
			{545809, "aggro", "cairnebloodhoofaggro02", "FOREVER!"},
			{2911900, "line", "vo_82_cairne_bloodhoof_01_m", "No, my son. Let it be."},
			{2911902, "line", "vo_82_cairne_bloodhoof_03_m", "You have helped this champion restore balance to the spirit realm, and balance is what we strive for."},
			{2911904, "line", "vo_82_cairne_bloodhoof_04_m", "I know, but we must wait for another time."},
		},
		sound = {
			{1362397, "ability", "spell_wr_thunderclap_impact_revamp_01"},
			{1362398, "ability", "spell_wr_thunderclap_impact_revamp_02"},
			{1362399, "ability", "spell_wr_thunderclap_impact_revamp_03"},
			{1362400, "ability", "spell_wr_thunderclap_impact_revamp_04"},
			{569222, "ability", "thunderclap"},
		},
	},
	[8] = {
		voice = {
			{563872, "pick", "voljingreeting01", "Spirits be with you stranger, how may I help?"},
			{563884, "pick", "voljingreeting02", "You come to consult the spirits?"},
			{563824, "pick", "voljingreeting03", "How can old Vol'jin help you?"},
			{563830, "pick", "voljinaggro03", "For the Darkspear Tribe!"},
			{773857, "pick", "vo_5.1_vol_voljin_greeting_02", "The spirits be restless."},
			{773861, "pick", "vo_5.1_vol_voljin_greeting_04", "These be the dark times."},
			{773863, "pick", "vo_5.1_vol_voljin_greeting_05", "The dog spear never gonna give up!"},
			{903193, "pick", "vo_54_or_voljin_event_07", "Heh, dark spirit never die."},
			{773793, "pick", "vo_5.1_vol_voljin_boss1_06", "Spirits be with ya!"},
			{851792, "pick", "vo_53_voljin_razor_start_06", "For the Horde."},
			{773865, "greet", "vo_5.1_vol_voljin_greet_01", "Watch me, Batman."},
			{773867, "greet", "vo_5.1_vol_voljin_greet_02", "Keep your eyes wide open."},
			{773869, "greet", "vo_5.1_vol_voljin_greet_03", "STAY CLOSE"},
			{773855, "greet", "vo_5.1_vol_voljin_greeting_01", "Spirits be witcher!"},
			{773859, "greet", "vo_5.1_vol_voljin_greeting_03", "How can O-Voltin help ya?"},
			{2124588, "greet", "vo_801_warchief_voljin_greeting_01", "Spirits be with ya."},
			{2124590, "greet", "vo_801_warchief_voljin_greeting_02", "The spirits be restless."},
			{2124591, "greet", "vo_801_warchief_voljin_greeting_03", "How can O-Vulgen help ya?"},
			{2124592, "greet", "vo_801_warchief_voljin_greeting_04", "These be the dark times"},
			{2124593, "greet", "vo_801_warchief_voljin_greeting_05", "The Darksphere never gonna give up!"},
			{563847, "aggro", "voljinaggro01", "You made big mistake, man."},
			{563841, "aggro", "voljinaggro02", "Here come the Fudu!"},
			{903195, "alert", "vo_54_or_voljin_intro_01", "Ain't no other way, man. We've got to stop Garrosh here and now, else we'll be running the rest of our lives."},
			{903197, "alert", "vo_54_or_voljin_intro_02", "They must have taken the docks, ha ha, we'll come to the fields of slaughter!"},
			{903199, "alert", "vo_54_or_voljin_intro_03", "TARANDA!"},
			{633941, "alert", "vo_voljin_pandaren_intro_event_01", "Warchief, what are you doing?"},
			{633943, "alert", "vo_voljin_pandaren_intro_event_02", "This be a mistake. I refuse to take part in this."},
			{633945, "alert", "vo_voljin_pandaren_intro_event_03", "Where you be finding these beasts, what kind of horde are you building?"},
			{773767, "line", "vo_5.1_hprog_voljin_beachvol_01", "The question is, what are we doing here? Ya bring this war to another corner of Azeroth and I wanna know why."},
			{773769, "line", "vo_5.1_hprog_voljin_beachvol_02", "All this bloodshed. Make everyone think twice about joining the Horde!"},
			{773771, "line", "vo_5.1_hprog_voljin_beachvol_03", "I will go. But only as a weakness for my people. Someone gotta keep you in check Garrosh."},
			{773773, "line", "vo_5.1_vol_voljin_assass_01", "Ooooh, these moku. They're workin' wicked dark magic here."},
			{773775, "line", "vo_5.1_vol_voljin_assass_02", "The Zorok, they're not born, they was created, flesh shaped and bent."},
			{773777, "line", "vo_5.1_vol_voljin_assass_03", "Ah, the speed of blackest of magicks, mon."},
			{773779, "line", "vo_5.1_vol_voljin_assass_04", "Garros, playing god, making monsters. This ain't what the Horde is about!"},
			{773781, "line", "vo_5.1_vol_voljin_assass_05", "Hey! Bye!"},
			{773783, "line", "vo_5.1_vol_voljin_boss1_01", "Hold up! There's something there!"},
			{773785, "line", "vo_5.1_vol_voljin_boss1_02", "Goodbye!"},
			{773787, "line", "vo_5.1_vol_voljin_boss1_03", "One of them lizard beasts. Fight on me brothers!"},
			{773789, "line", "vo_5.1_vol_voljin_boss1_04", "This will help!"},
			{773791, "line", "vo_5.1_vol_voljin_boss1_05", "STAY IN THE FIGHT!"},
			{773795, "line", "vo_5.1_vol_voljin_boss1_07", "Use this to heal yourself!"},
			{773797, "line", "vo_5.1_vol_voljin_boss1_08", "Pull them to the trap!"},
			{773799, "line", "vo_5.1_vol_voljin_boss1_09", "law him into the trap!"},
			{773801, "line", "vo_5.1_vol_voljin_boss1_10", "I set up a drop!"},
			{773803, "line", "vo_5.1_vol_voljin_boss1_11", "Lead him into this drop!"},
			{773805, "line", "vo_5.1_vol_voljin_boss1_12", "Get these beasts off of me!"},
			{773807, "line", "vo_5.1_vol_voljin_boss1_13", "DARE BE OTHERS!"},
			{773809, "line", "vo_5.1_vol_voljin_boss1_14", "Have you thought these things before?"},
			{773811, "line", "vo_5.1_vol_voljin_boss1_15", "It's like they got weapons, but no brains."},
			{773813, "line", "vo_5.1_vol_voljin_boss1_16", "One of you man the guns, the wrist on foot."},
			{773815, "line", "vo_5.1_vol_voljin_boss1_17", "Kill anything that squirms."},
			{773817, "line", "vo_5.1_vol_voljin_boss1_18", "Get the sorcerer!"},
			{773819, "line", "vo_5.1_vol_voljin_boss1_19", "Get these bees off of the boat!"},
			{773821, "line", "vo_5.1_vol_voljin_boss1_20", "Here! Stop the board here!"},
			{773823, "line", "vo_5.1_vol_voljin_boss1_21", "Gris, you got the boat. There is the air with me."},
			{773825, "line", "vo_5.1_vol_voljin_boss2_01", "This be some kind of spawning chamber!"},
			{773827, "line", "vo_5.1_vol_voljin_boss2_02", "And that be one ugly mother."},
			{773829, "line", "vo_5.1_vol_voljin_boss2_03", "Be careful! The roof be comin' down!"},
			{773831, "line", "vo_5.1_vol_voljin_boss2_04", "Something unnatural about these creatures."},
			{773833, "line", "vo_5.1_vol_voljin_boss2_05", "Voodoo."},
			{773835, "line", "vo_5.1_vol_voljin_boss2_06", "Watch me back while I investigate."},
			{773837, "line", "vo_5.1_vol_voljin_final_01", "The Warchief chose his hand."},
			{773839, "line", "vo_5.1_vol_voljin_final_02", "This be what the Horde come to. Kill it it's own. Ahh, we can't let this happen."},
			{773841, "line", "vo_5.1_vol_voljin_final_03", "Champions, I need ya."},
			{773843, "line", "vo_5.1_vol_voljin_final_04", "Go back to the warchief, tell him I'm dead, stay close to him, watch him."},
			{773845, "line", "vo_5.1_vol_voljin_final_05", "You and me, we move to take him out when the time is right."},
			{773847, "line", "vo_5.1_vol_voljin_final_06", "Orders are like me. You gotta find them."},
			{773849, "line", "vo_5.1_vol_voljin_final_07", "Swear. Swear the blood out with me."},
			{773851, "line", "vo_5.1_vol_voljin_final_08", "Ah, it be done. We brought us in this until the end."},
			{773853, "line", "vo_5.1_vol_voljin_final_09", "I'm going to disappear for a while. Don't forget about me."},
			{773871, "line", "vo_5.1_vol_voljin_open_01", "Everyone be here now, let's get this done with!"},
			{773873, "line", "vo_5.1_vol_voljin_open_02", "As do Warchief commands."},
			{773875, "line", "vo_5.1_vol_voljin_open_03", "I'm glad you're here to watch me back, I don't like the look of Garrosh's goons."},
			{773877, "line", "vo_5.1_vol_voljin_open_04", "Let's mount up and move out."},
			{773879, "line", "vo_5.1_vol_voljin_open_05", "Skull'd said it's ancient magic in these caves, Warchief wants him checked out."},
			{773881, "line", "vo_5.1_vol_voljin_open_06", "them Siroc begotten to give. Let's take care of him."},
			{851766, "line", "vo_53_voljin_alliance_trust_01", "Hmm, very well. You earn me trust. I will put me faith in the Alliance to do the right thing."},
			{851768, "line", "vo_53_voljin_alliance_trust_02", "The dark spear and her allies will attack old grandma by land, so that you can attack her by sea. It be the only way."},
			{851770, "line", "vo_53_voljin_alliance_trust_03", "If we survive this, maybe some day I call you friend."},
			{851772, "line", "vo_53_voljin_oldtimes_01", "Look at us three, back to the sands of old Durata. It'd be just like old times."},
			{851774, "line", "vo_53_voljin_razor_finale_01", "It be done! Raise or heal is ours! The Warchief probably see the fires all the way from Grommash Hold."},
			{851776, "line", "vo_53_voljin_razor_finale_02", "Dain, we be needin' ya support. Raise a heel be but an outpost. The walls of Ogrimmar be fortified since the cataclysm."},
			{851778, "line", "vo_53_voljin_razor_finale_03", "Lothamar be ready to strike once he finish with the Isle of Tundra and the Banshee Queen need no excuse but they board across the sea without your strength or can't breach the city. I need tauren arms.\""},
			{851780, "line", "vo_53_voljin_razor_finale_04", "Hm?"},
			{851782, "line", "vo_53_voljin_razor_start_01", "Regroup! We've pressed the advantage! Before the war chief fortifies Razorheel, we take it for the revolution and close off the road to the Barrens."},
			{851784, "line", "vo_53_voljin_razor_start_02", "Anyone who can still fight, come with me!"},
			{851786, "line", "vo_53_voljin_razor_start_03", "We need your man."},
			{851788, "line", "vo_53_voljin_razor_start_04", "You set one foot in Okramar. He'll scream gonna bury a knife in your neck!"},
			{851790, "line", "vo_53_voljin_razor_start_05", "I wonder you see such tings?"},
			{851794, "line", "vo_53_voljin_razor_start_07", "Dark spear with me, we ride, no sleep till our grandma!"},
			{851796, "line", "vo_53_voljin_senjin_01", "They come! Hellscream tinkers on people gonna roll right over!"},
			{851798, "line", "vo_53_voljin_senjin_02", "Time to show this warchief the fury of the dog's spear!"},
			{851800, "line", "vo_53_voljin_senjin_03", "Hold! Let them run away. Hellscream will execute them as cowards if they go back. Sinjin village is safe!"},
			{903181, "line", "vo_54_or_voljin_event_01", "They be heroes, no doubt about that."},
			{903183, "line", "vo_54_or_voljin_event_02", "THE BEAST BEAST LANE!"},
			{903185, "line", "vo_54_or_voljin_event_03", "Garrosh be concealing a whole hidden base. Where did his lust for power take him?"},
			{903187, "line", "vo_54_or_voljin_event_04", "Bane, you and your warriors hold this junction. These heroes should forge ahead and flush the warchief out of hiding."},
			{903189, "line", "vo_54_or_voljin_event_05", "People be dyin' up above! The city's in chaos! I'm gonna finish it! Stop the bloodshed! I'll come back for ya!"},
			{903191, "line", "vo_54_or_voljin_event_06", "It's gonna be fine, Bane. We gonna find Thrall, gonna kill the Warchief, gonna avenge your father."},
			{1124368, "line", "vo_62_voljin_council_01", "The Horde be counting on your commander. Find us a ship right so we can surround Tenan!"},
			{1124369, "line", "vo_62_voljin_docks_01", "We're counting on ya, Commander! Bring victory to the Horde!"},
			{1455743, "line", "vo_703_warchief_voljin_01_m", "Warriors are the horde. Get your axes and sharpen your spears. The Burning Legion has returned to our world!"},
			{1248632, "line", "vo_70_voljin_01", "More beasts from the flame!"},
			{1248654, "line", "vo_70_voljin_02", "That Great Ball of Fair Fire is coming this way!"},
			{1248689, "line", "vo_70_voljin_03", "We've got to hold this reach, no matter the cost!"},
			{1248705, "line", "vo_70_voljin_04", "Even more demons be pouring from that portal! GET READY!"},
			{1248707, "line", "vo_70_voljin_05", "You"},
			{1248741, "line", "vo_70_voljin_06", "Good thing. We don't got much beach left to retreat to."},
			{1248745, "line", "vo_70_voljin_07", "Listen up, there's only one way off at this beach, and it'd be through all those demons ahead of us. But they don't know who they'd be dealing with. Let's show them what it means to be hard!"},
			{1248761, "line", "vo_70_voljin_08", "DIE!"},
			{1248763, "line", "vo_70_voljin_09", "This one's mine!"},
			{1248765, "line", "vo_70_voljin_10", "FOR THE HORDE!"},
			{1248775, "line", "vo_70_voljin_11", "Hoard! Make for them crystals! We're gonna see if your hunch is right!"},
			{1248779, "line", "vo_70_voljin_12", "TWO MORE TO GO!"},
			{1248783, "line", "vo_70_voljin_13", "Keep it up! We almost got him!"},
			{1248787, "line", "vo_70_voljin_14", "You gonna die just like all the others?"},
			{1248800, "line", "vo_70_voljin_15", "Looks like you chose the wrong side!"},
			{1248808, "line", "vo_70_voljin_16", "He's never gonna get used to your calling me that."},
			{1248812, "line", "vo_70_voljin_17", "Let's get moving!"},
			{1248814, "line", "vo_70_voljin_18", "Sylvani's ship must have crashed just ahead!"},
			{1248818, "line", "vo_70_voljin_19", "Yamaan, this ain't the same Legion."},
			{1248822, "line", "vo_70_voljin_20", "That's no invasion force, that's an army!"},
			{1248828, "line", "vo_70_voljin_21", "LET'S MOVE!"},
			{1248832, "line", "vo_70_voljin_22", "You look like you can use a hand!"},
			{1248854, "line", "vo_70_voljin_23", "A new sign of Tyrian!"},
			{1248902, "line", "vo_70_voljin_24", "AND BE RETREATED!"},
			{1248908, "line", "vo_70_voljin_25", "All the horde! Get to thrall!"},
			{2061467, "line", "vo_801_warchief_voljin_01_m", "Show them, leader of Zandalar, show the blade to those that need to see it the most, give them peace."},
			{2061468, "line", "vo_801_warchief_voljin_02_m", "to these shores against your father's will. You'll learn the secrets of G'huun when no one be listening."},
			{2061469, "line", "vo_801_warchief_voljin_03_m", "You said in motion what we needed to save your people. Now more than ever, they be calling for a leader they can love. And trust."},
			{2061470, "line", "vo_801_warchief_voljin_04_m", "Show them the blade. Become the symbol they need."},
			{2061471, "line", "vo_801_warchief_voljin_05_m", "Noooooooosss"},
			{2061472, "line", "vo_801_warchief_voljin_06_m", "Loss. Loss. So much loss. So many without guidance. So many without justice. Their hope be taken by Gahun."},
			{2408379, "line", "vo_81_warchief_voljin_01_m", "Delanji, your voice be a mighty one!"},
			{2408380, "line", "vo_81_warchief_voljin_02_m", "Bane, your heart beats strong and true, just like your father. I be glad the demons didn't take ya."},
			{2408381, "line", "vo_81_warchief_voljin_03_m", "Ah, my young friend, death be dark, be memory, not be what it once was."},
			{2408382, "line", "vo_81_warchief_voljin_04_m", "Ah, the memory. He'd be denied me by the shadows. Shadows that... that be comin' for ya. Watch out!"},
			{2408383, "line", "vo_81_warchief_voljin_05_m", "Something. Not be right that day. The demons. The bleeds sleep past me, God."},
			{2408384, "line", "vo_81_warchief_voljin_06_m", "As if the Lord themselves had forsaken me."},
			{2408385, "line", "vo_81_warchief_voljin_07_m", "Like they be doing now, cannot hear them champion, the voices are in lower, be silent."},
			{2408386, "line", "vo_81_warchief_voljin_08_m", "I've been calling to Bwonsamdi for a long time. He'll not be here with me, or he'll be chosen not to answer."},
			{2408387, "line", "vo_81_warchief_voljin_09_m", "Lich King, the voice I heard as I be dying, telling me to name Sylvanas Warchief, was it yours?"},
			{2408388, "line", "vo_81_warchief_voljin_10_m", "And my spirit, being trapped in this world, is that you're doing"},
			{2408389, "line", "vo_81_warchief_voljin_11_m", "I was expecting to see your Bwonsamdi. Washadra, Highreek, Iniyara Loa."},
			{2408390, "line", "vo_81_warchief_voljin_12_m", "There was a presence, something moving in the shadows, something powerful."},
			{2408391, "line", "vo_81_warchief_voljin_13_m", "I remember he'd taken me somewhere, but the memory of where? Be hidden from me, to keep me from sharing the truth."},
			{2408392, "line", "vo_81_warchief_voljin_14_m", "The truth that it might not be the lore who wanted Sylvanas to be warchief, but something far more powerful."},
			{2408393, "line", "vo_81_warchief_voljin_15_m", "Ah yeah, speak with me if the artist not be to your liking."},
			{2408394, "line", "vo_81_warchief_voljin_16_m", "Queen of the Valkyr. My spirit was sent to the other side. Then returned. Was this your dream?"},
			{2408395, "line", "vo_81_warchief_voljin_17_m", "Who'd be havin' such power? Could it be the same one who bid me to name Sylvanas Warchief?"},
			{2408396, "line", "vo_81_warchief_voljin_18_m", "So, whoever whispered to me is not the same as who sent me back."},
			{2410899, "line", "vo_81_warchief_voljin_19_m", "For now, I gonna keep searching for answers. If there be no enemies gathering in the shadows, then I best be hunting them before they be hunting us."},
			{2410904, "line", "vo_81_warchief_voljin_20_m", "I remember dying, I remember glimpsing the other side"},
			{2413815, "line", "vo_81_warchief_voljin_21_m", "The Lich King didn't bring me back. I hear he be claiming she don't got the mojo. One someday be as confused as the rest of us. And none of them were eager to see Sylvanas in charge."},
			{2413816, "line", "vo_81_warchief_voljin_22_m", "You"},
			{2413817, "line", "vo_81_warchief_voljin_23_m", "Zandalar still stands, because of your courage, Talanji. Your father was mired in the old ways, dreamer of a cruel empire lost to time."},
			{2413818, "line", "vo_81_warchief_voljin_24_m", "Would you be the first to look to the future, to see what the trolls can become? You be young, would you be righteous? Call on me, spirit, if you ever need advice from an old chief then."},
			{3723498, "line", "vo_901_voljin_01_m", "One softy, you're being too important to summon me yourself."},
			{3723499, "line", "vo_901_voljin_02_m", "That voice...whispering...is the poison be burning in me veins! Windrunner!"},
			{3723500, "line", "vo_901_voljin_03_m", "It'd be me who named Sylvanas Warchief, but Mo'zala and the Jailer, they'd be pulling the strings all along."},
			{3723501, "line", "vo_901_voljin_04_m", "Wait, I got something to say."},
			{3723502, "line", "vo_901_voljin_05_m", "Want some tea? There'd be no escaping the mall, yeah? If I'd be going in."},
			{3723503, "line", "vo_901_voljin_06_m", "Didn't it be time I said things right? No way I be lettin' mozala get the last laugh."},
			{3723504, "line", "vo_901_voljin_07_m", "The more be waiting, and the spirit we gonna save."},
			{3723505, "line", "vo_901_voljin_08_m", "This place, it'd be worse than I imagined. I'd be sensing traces of the spirit nearby."},
			{3723506, "line", "vo_901_voljin_09_m", "I be tracking the spirit for ya, but that pure, anything more, then I gonna risk being stuck here forever."},
			{3723507, "line", "vo_901_voljin_10_m", "We've been spotted, man!"},
			{3723508, "line", "vo_901_voljin_11_m", "Hmm, they tortured the spirit. Then moved it somewhere else. I got the trail."},
			{3723509, "line", "vo_901_voljin_12_m", "Look out!"},
			{3723510, "line", "vo_901_voljin_13_m", "This be a tough one to track, even for a Shadowhunter. Let's go!"},
			{3723511, "line", "vo_901_voljin_14_m", "And the ossamine, a wild god from the war of the ancients."},
			{3723512, "line", "vo_901_voljin_15_m", "Oh Walker, I'd be sensing no one nearby."},
			{3723513, "line", "vo_901_voljin_16_m", "We're not believing yet. Not worried below or trapped here."},
			{3723514, "line", "vo_901_voljin_17_m", "To Noah, be somewhere across the beach, we'll best be moving."},
			{3723515, "line", "vo_901_voljin_18_m", "Highreek, I heard his greet when he be dying in Nazmir."},
			{3723516, "line", "vo_901_voljin_19_m", "There'll be more lower this way. Hurry!"},
			{3723517, "line", "vo_901_voljin_20_m", "Shaja, once some did only, she'd been consumed by her own priestess."},
			{3723518, "line", "vo_901_voljin_21_m", "There be one lower lift, one almost gone."},
			{3723519, "line", "vo_901_voljin_22_m", "Rezaan, the Noah of Jeans. We need to break that barrier!"},
			{3723520, "line", "vo_901_voljin_23_m", "I be countin' on ya, take me anima, and save Rezan!"},
			{3723521, "line", "vo_901_voljin_24_m", "No, Rezan, we're gonna take it out of here. Get your streets back."},
			{3723522, "line", "vo_901_voljin_25_m", "No, I be just an old shadow hunter. Our people, they be needing you."},
			{3723523, "line", "vo_901_voljin_26_m", "Razon, I'll not be wasting your gift. Your name gonna be remembered, always."},
			{3723524, "line", "vo_901_voljin_27_m", "I can't be staying anymore any longer. Bring the spirit home to Ardenweald."},
			{3723525, "line", "vo_901_voljin_28_m", "I be deeply honored, your majesty, Champion, thank you for all you've done for me, in life and in death."},
			{3723526, "line", "vo_901_voljin_29_m", "Looks like old Vol'jin be startin' a new hunt, after I be gettin' some rest."},
			{3723527, "line", "vo_901_voljin_30_m", "Misie-nya!"},
			{3723528, "line", "vo_901_voljin_31_m", "Spirits be watching, the good and the bad."},
			{3723529, "line", "vo_901_voljin_32_m", "For the dark spear and all the tribes."},
			{3723530, "line", "vo_901_voljin_33_m", "We always be interested in Dormann."},
			{3723531, "line", "vo_901_voljin_34_m", "Keep your eyes open."},
			{3723532, "line", "vo_901_voljin_35_m", "Warvoldgen, gonna be waiting."},
			{3723533, "line", "vo_901_voljin_36_m", "Watch the shadows"},
			{3723534, "line", "vo_901_voljin_37_m", "How can old Vol'ja be here, Vinya?"},
			{3723535, "line", "vo_901_voljin_38_m", "SPIRIT SPEWITCHA"},
			{3723536, "line", "vo_901_voljin_39_m", "These be dark times."},
			{3723537, "line", "vo_901_voljin_40_m", "What you be needing, ma'am?"},
			{3723538, "line", "vo_901_voljin_41_m", "The spirits be more restless than ever."},
			{3723539, "line", "vo_901_voljin_42_m", "You'll be standing ready."},
			{3723540, "line", "vo_901_voljin_43_m", "I'd be listening."},
			{3723541, "line", "vo_901_voljin_44_m", "Careful now. That wouldn't be the first one me ex for porking too much."},
			{3723542, "line", "vo_901_voljin_45_m", "It'd be hard to be a shadow hunter when your spirit don't be cast in shadows."},
			{3723543, "line", "vo_901_voljin_46_m", "Hey man, let's be taken back to me time is war chief. Ya done yet? Ah, yeah man, me too."},
			{563851, "line", "vo_qe_dt_voljin_eievent01", "I have something to show you. It'd be easier to understand if you see it yourself."},
			{563853, "line", "vo_qe_dt_voljin_eievent02", "There be no question why Garrosh, he gave you the title because you be Grams son and because the people be worth no war hero."},
			{563839, "line", "vo_qe_dt_voljin_eievent03", "I think you'd be more like your father than your thought, even without the demon blood."},
			{563875, "line", "vo_qe_dt_voljin_eievent04", "You'll be no war chief of mine, you not earn my respect, and I'll not be seen or destroyed by your foolish thirst for war."},
			{563880, "line", "vo_qe_dt_voljin_eievent05", "I know exactly what I'll be doing about it, son of Hellscream. I'll watch and wait as your people slowly become aware of your ineptitude. I'll laugh as they grow to despise you, as I do."},
			{563890, "line", "vo_qe_dt_voljin_eievent06", "And when that time comes, that your failure is complete and your power is meaningless, I will be there to end your rule, swiftly and silently."},
			{563883, "line", "vo_qe_dt_voljin_eievent07", "You will spend your reign glancing over your shoulder and fearing the shadows. For when the time comes and your blood be slowly draining out, you will know exactly who fired the arrow that pierced your black heart."},
			{563823, "line", "vo_qe_dt_voljin_eievent08", "And you yours, Warchief."},
			{563843, "line", "vo_qe_dt_voljin_eievent09", "The Darkspear are here because I led them here. Orgrimmar be no home, long as it be under Hellscream's hand.\""},
			{563822, "line", "vo_qe_dt_voljin_eievent10", "Still I fear I was letting my temper drive me to be in rash. Thrall devoted himself to making the horde what it is, so I've no eagerness to be leaving it on a whim. This will be needing much more thought."},
			{563848, "line", "vo_qe_dt_voljin_eievent11", "but these be worries for all their minds. You still have much to learn. Go help the people of the Darkspear. I'm sure we'll be speaking again real soon."},
			{563850, "line", "vo_qe_dt_voljin_eievent12", "The sea witch is dead, our home is reclaimed, but our future still be uncertain."},
			{563865, "line", "vo_qe_dt_voljin_eievent13", "I have no love for Garrosh, that much is sure, but leaving the Horde is not a decision I be taking lightly."},
			{563869, "line", "vo_qe_dt_voljin_eievent14", "There's only one with the answers I seek, you can stay and watch if you like."},
			{563887, "line", "vo_qe_dt_voljin_eievent15", "Thrall. I'm glad you be well. There were rumors otherwise."},
			{563877, "line", "vo_qe_dt_voljin_eievent16", "I must beg your counsel, my friend. I can't be standing by Garrosh while he be turnin' our people against each other for the sake of war. My respect for you does not extend to this new horde. I'm takin' a lead and my people away.\""},
			{563891, "line", "vo_qe_dt_voljin_eievent17", "I understand brother. I will think on this and be troubling ya no further. You have a world to be savin'"},
			{563870, "line", "vo_qe_dt_voljin_eievent18", "You'd be strong and proud, youngblood. The dark spear will be honored to have you fight beside him.\""},
			{563836, "line", "vo_qe_dt_voljin_eievent19", "These be dark times, but our people will be staying with the Horde for the good of all."},
			{563831, "line", "vo_qe_dt_voljin_eievent20", "Thrall's words be true, they always be. The Horde is much more than just a few old stubborn leaders, and a handful of heroes from Northrend. The people be cryin' Garrosh's name, at least for now."},
			{563859, "line", "vo_qe_dt_voljin_eievent21", "Still, I'd be hoping Thrall will return to us one day. The future right now be looking very grim, and very bloody."},
			{563833, "line", "vo_qe_dt_voljin_eievent22", "Go now, make the dark spear proud. There are many wars ahead of us, and I'm sure you'll be having a part of play in all of them."},
			{563885, "line", "vo_qe_dt_voljin_eievent23", "You were foolish to come here, sea witch. You escaped our vengeance once, but the dark spear tribe will not abide your trespassing again."},
			{563838, "line", "vo_qe_dt_voljin_eievent24", "The darkspear shall never give in to your kinds, Ajira. We're stronger than you ever be.\""},
			{563832, "line", "vo_qe_dt_voljin_eievent25", "It'd be done. Our ancient enemy is defeated."},
			{563840, "line", "vo_qe_dt_voljin_eievent26", "I've been waiting a long time for a chance to avenge my father. A great weight has been lifted from my shoulders."},
			{563867, "line", "vo_qe_dt_voljin_eievent27", "I must be returning to Darkspear Hold. Please meet me there once Vanira is done with her healing of the boy.\""},
		},
